storedProcedures.definition:
-- =========== TS-QC:UPDATED ====================
-- Author		 : TakroSystem\Ahmadnejad
-- Create date   : 1386/02/02
-- Viewed By	 : 
-- Last Modified : 1393/03/11
-- Last Modifier : TakroSystem\Zia
-- ----------------------------------------------
-- Description	 : < تراز آزمایشی > 
-- ==============================================
Create  PROCEDURE [acc].[RptAcc_TrialBalance1]
	@PartNo				TinyInt, -- شماره بخش
	@PartLen			TinyInt, -- طول لایه - اگر بخش یک باشد یا بخش یک نباشد ولی کد بصورت کامل خواسته شود این پارامتر طول کامل کد والا طول کد در آن بخش را می پذیرد
	@ParentLen			TinyInt, -- طول لایه پدر - اگر بخش یک باشد یا بخش یک نباشد ولی کد بصورت کامل خواسته شود این پارامتر طول کامل کد والا طول کد در آن بخش را می پذیرد
	@AcntCode1From		VarChar(20) = Null,
	@AcntCode1To		VarChar(20) = Null,
	@AcntCode2From		VarChar(20) = Null,
	@AcntCode2To		VarChar(20) = Null,
	@AcntCode3From		VarChar(20) = Null,
	@AcntCode3To		VarChar(20) = Null,
	@AcntCode4From		VarChar(20) = Null,
	@AcntCode4To		VarChar(20) = Null,
	@SerialNoFrom		Int = Null,
	@SerialNoTo			Int = Null,
	@OldSerialNoFrom	Int = Null,
	@OldSerialNoTo		Int = Null,
	@DateFrom			Char(10) = Null,
	@DateTo				Char(10) = Null,
	@SortMode			int = 0, 
	@AcntGroup			VarChar(20) = Null,
	@AcntName			NVarChar(50) = Null,
	@RepOptions			VarChar(30) = '100100100100100100',  -- bit array options
	@RepInfo			NVarChar(100) = '1@1@1@1',
	@ExtraParams		NVarChar(200) = '-1@-1@-1@-1@-1@-1@-1@-1'
--WITH ENCRYPTION
AS

Declare @StrSelect	NVarChar(max);
Declare @StrFrom	NVarChar(max);
Declare @StrWhere	NVarChar(max);
Declare @StrWhereG	NVarChar(max);

DECLARE	@LangID		Char(1);
DECLARE	@SessionNo	Int; 
DECLARE	@ReportID	Int; 
DECLARE	@UserID		Int; 

Declare @iAcntStart	TinyInt;
Declare @iAcntLen	TinyInt;
Declare @iAcntLenW	TinyInt;

Declare @xStart	TinyInt;
Declare @xLen	TinyInt;

Declare @Part1Start	TinyInt;
Declare @Part1Len	TinyInt;

Declare @Part2Start	TinyInt;
Declare @Part2Len	TinyInt;

Declare @Part3Start	TinyInt;
Declare @Part3Len	TinyInt;

Declare @Part4Start	TinyInt;
Declare @Part4Len	TinyInt;

Declare @LimitState1	SmallInt;
Declare @LimitState2	SmallInt;
Declare @LimitState3	SmallInt;
Declare @LimitState4	SmallInt;

Declare @StrWhere2		NVarChar(max);
DECLARE @StrWhereSLC	NVarChar(max);
DECLARE @StrWhereSrl	NVarChar(max);
DECLARE @StrWhereDat	NVarChar(max);
DECLARE @StrAcntWhere	NVarChar(max);

declare @AcntGroupTo	VarChar(20); 
declare @DebitRemainFr	BigInt;
declare @DebitRemainTo	varchar(20);
declare @CreditRemainFr	BigInt;
declare @CreditRemainTo	BigInt;
declare @DebitCycleFr	BigInt;
declare @DebitCycleTo	BigInt;
declare @CreditCycleFr	BigInt;
declare @CreditCycleTo	varchar(20);
DECLARE	@SourceProcessNo	VARCHAR(30);

declare @UseExtraCodes		bit;
declare @ZeroCycle			bit; -- شامل کد حسابهائی که اصلاً گردشی در طول دوره ندارند باشد یا نه؟
declare @ShowLastDate		bit; -- شامل ستون آخرین تاریخ بدهکاری یا بستانکاری باشد یا نه؟
declare @DistinctPart		bit; -- فقط کدهای آن بخش بیاید؟ اگر نه کد کامل خواهد آمد
declare @UseSlcCodes		bit; -- از کدهای انتخابی استفاده شود یا نه؟
declare @ShowAllCodes		bit; -- بخش قبلی علاوه بر بخش جاری آورده شود؟
declare @UserIsAdmin		bit; -- کاربر اعلام شده مدیر است یا نه؟
declare @ShowPrimary		Bit; -- شامل کدهای افتتاحیه باشد یا نه؟
declare @ShowFinish			Bit; -- شامل کدهای اختتامیه باشد یا نه؟
declare @ShowClosed			Bit; -- شامل کد بستن حساب باشد یا نه؟
declare @PrimDocInRemain	Bit; -- سند افتتاحیه جزو مانده حساب شود یا طی دوره؟
declare @UseCurrency		Bit; -- واحد ارزی استفاده شود؟
declare @ZeroRemain1		bit; -- شامل کد حسابهائی که مانده آنها صفر است باشد یا نه؟
declare @ZeroRemain2		Bit; 
declare @ZeroRemain3		Bit; 
declare @ZeroRemain12		Bit; 
declare @ZeroRemain23		Bit; 
declare @ZeroRemain31		Bit; 
declare @SharingDocs		Bit; 
declare @UseLastLayer		Bit; 

declare @CurrencyTypeID		Varchar(20); 
declare @CurrencyTypeName	Varchar(50); 
declare @AcntName1	Varchar(1000); 
declare @AcntName2	Varchar(1000); 
declare @AcntName3	Varchar(1000); 
declare @AcntName4	Varchar(1000); 
declare @AcntName5	Varchar(1000); 
declare @AcntName6	Varchar(1000); 
declare @AcntName7	Varchar(1000); 
declare @AcntName8	Varchar(1000); 

DECLARE @CampaignID				int;
DECLARE @VisitPathID1			int;
DECLARE @VisitPathID2			int;
DECLARE @VisitPathID3			int;
DECLARE @VisitPathID4			int;
DECLARE @SalesRoomClass			int;
DECLARE @CustomerPartStart		VarChar(20);
DECLARE @CustomerPartLayerLen	VarChar(20);

DECLARE @SortCreDebMode as varchar(20);
DECLARE @SortAscDescMode as varchar(20);
Declare @Nosoon	TinyInt;

DECLARE @AcntStart1		int;
DECLARE @AcntLen1		int;
DECLARE @AcntStart2		int;
DECLARE @AcntLen2		int;
DECLARE @AcntStart3		int;
DECLARE @AcntLen3		int;
DECLARE @AcntStart4		int;
DECLARE @AcntLen4		int;
DECLARE @PartNumber		int;

	
DECLARE @Layer11	int
DECLARE @Layer12	int
DECLARE @Layer13	int
DECLARE @Layer14	int

DECLARE @Layer21	int
DECLARE @Layer22	int
DECLARE @Layer23	int
DECLARE @Layer24	int

DECLARE @Layer31	int
DECLARE @Layer32	int
DECLARE @Layer33	int
DECLARE @Layer34	int

DECLARE @Layer41	int
DECLARE @Layer42	int
DECLARE @Layer43	int
DECLARE @Layer44	int
DECLARE @SqlLayer	Varchar(max)
DECLARE @AcntCode1	VarChar(1024);
DECLARE @AcntCode2	VarChar(1024);
DECLARE @AcntCode3	VarChar(1024);
DECLARE @AcntCode4	VarChar(1024);
	
BEGIN -- ============================ S T A R T =====================================================

	SET NOCOUNT ON;

	--- init -------------------------------------------------------------------
	IF (@RepInfo	Is Null)	SET @RepInfo = '1@1@1@1'
	IF (@RepOptions	Is Null)	SET @RepOptions = '100100100100100100'

	SET @DebitRemainFr	= pub.funSplitString(@ExtraParams, '@', 1);
	SET @DebitRemainTo	= pub.funSplitString(@ExtraParams, '@', 2);
	SET @CreditRemainFr	= pub.funSplitString(@ExtraParams, '@', 3);
	SET @CreditRemainTo	= pub.funSplitString(@ExtraParams, '@', 4);
	SET @DebitCycleFr	= pub.funSplitString(@ExtraParams, '@', 5);
	SET @DebitCycleTo	= pub.funSplitString(@ExtraParams, '@', 6);
	SET @CreditCycleFr	= pub.funSplitString(@ExtraParams, '@', 7);
	SET @CreditCycleTo	= pub.funSplitString(@ExtraParams, '@', 8);
	-- 9, 10 is used
	SET @AcntGroupTo	= pub.funSplitString(@ExtraParams, '@', 11);
 
	
	SET @CurrencyTypeID	= pub.funSplitString(@ExtraParams, '@', 12);
	SET @CurrencyTypeName = pub.funSplitString(@ExtraParams, '@', 13);
	SET @AcntName1 = pub.funSplitString(@ExtraParams, '@', 14);
	SET @AcntName2 = pub.funSplitString(@ExtraParams, '@', 15);
	SET @AcntName3 = pub.funSplitString(@ExtraParams, '@', 16);
	SET @AcntName4 = pub.funSplitString(@ExtraParams, '@', 17);
	SET @AcntName5 = pub.funSplitString(@ExtraParams, '@', 18);
	SET @AcntName6 = pub.funSplitString(@ExtraParams, '@', 19);
	SET @AcntName7 = pub.funSplitString(@ExtraParams, '@', 20);
	SET @AcntName8 = pub.funSplitString(@ExtraParams, '@', 21);
	SET @SortCreDebMode =pub.funSplitString(@ExtraParams, '@', 22);
	SET @SortAscDescMode =pub.funSplitString(@ExtraParams, '@', 23);
	SET @Nosoon =pub.funSplitString(@ExtraParams, '@', 24);
		
	SET @LangID		= pub.funSplitString(@RepInfo, '@', 1);
	SET @SessionNo	= pub.funSplitString(@RepInfo, '@', 2);
	SET @ReportID	= pub.funSplitString(@RepInfo, '@', 3);
	SET @UserID		= pub.funSplitString(@RepInfo, '@', 4);
	SET @CampaignID	= pub.funSplitString(@RepInfo, '@', 6);
	SET @VisitPathID1	= pub.funSplitString(@RepInfo, '@', 7);
	SET @VisitPathID2	= pub.funSplitString(@RepInfo, '@', 8);
	SET @VisitPathID3	= pub.funSplitString(@RepInfo, '@', 9);
	SET @VisitPathID4	= pub.funSplitString(@RepInfo, '@', 10);
	SET @SalesRoomClass	= pub.funSplitString(@RepInfo, '@', 11);

	SET @UseExtraCodes	= Substring(@RepOptions, 1, 1); 
	SET @ZeroRemain1	= Substring(@RepOptions, 2, 1); 
	SET @ZeroRemain2	= Substring(@RepOptions, 3, 1); 
	SET @ZeroCycle		= Substring(@RepOptions, 4, 1); 
	SET @ShowLastDate	= Substring(@RepOptions, 5, 1); 
	-- 6 show desc
	-- 7 show addr
	SET @DistinctPart		= Substring(@RepOptions, 8, 1); 
	SET @UseSlcCodes		= Substring(@RepOptions, 9, 1); 
	SET @ShowAllCodes		= Substring(@RepOptions, 10, 1);
	SET @UserIsAdmin		= Substring(@RepOptions, 11, 1);
	SET @ShowPrimary		= Substring(@RepOptions, 12, 1);
	SET @ShowFinish			= Substring(@RepOptions, 13, 1);
	SET @ShowClosed			= Substring(@RepOptions, 14, 1);
	SET @PrimDocInRemain	= Substring(@RepOptions, 15, 1);
	SET @UseCurrency		= Substring(@RepOptions, 16, 1);
	-- 17 sum groups 
	SET @ZeroRemain3		= Substring(@RepOptions, 18, 1); -- 18
	SET @ZeroRemain12		= Substring(@RepOptions, 19, 1); -- 19
	SET @ZeroRemain23		= Substring(@RepOptions, 20, 1); -- 20
	SET @ZeroRemain31		= Substring(@RepOptions, 21, 1); -- 21
	
	--------------------------------------------------------------------
	Declare @CustomerPartNo AS Tinyint
	
	SET @CustomerPartNo = 0
	
	SELECT @CustomerPartNo = SettingValue
	FROM pub.tblSettings
	WHERE SettingKey = 'AcntPartNumberForRemainCalculation'
			
	--if @SortMode =0 AND @DistinctPart = 1
	--	SET @ParentLen = 0

	if LEN(@RepOptions) > 21
		SET @SourceProcessNo= Substring(@RepOptions, 22, 1) -- 22
	else
		SET @SourceProcessNo= '0'

	if LEN(@RepOptions) > 22
		SET @SharingDocs = Substring(@RepOptions, 23, 1) -- 23
	else
		SET @SharingDocs = 0

	if LEN(@RepOptions) > 23
		SET @UseLastLayer = Substring(@RepOptions, 24, 1) -- 24
	else
		SET @UseLastLayer = 1
	---------------------------------------------------------------------------
	SET @StrWhere = '';
	SET @StrWhere2 = '';
	SET @StrWhereSrl = '';
	SET @StrWhereDat = '';
	SET @StrAcntWhere = ''

	If @UserIsAdmin = 1
	Begin
		SET	@LimitState1 = 1
		SET	@LimitState2 = 1
		SET	@LimitState3 = 1
		SET	@LimitState4 = 1
	End
	Else
	Begin
		SELECT	TOP 1 @LimitState1 = AccessAllCode
		FROM	acc.tblAcntRng
		WHERE	(UserID = @UserID) AND (PartNumber = 1)

		SET @LimitState1 = IsNull(@LimitState1, -1);

		SELECT	TOP 1 @LimitState2 = AccessAllCode
		FROM	acc.tblAcntRng
		WHERE	(UserID = @UserID) AND (PartNumber = 2)

		SET @LimitState2 = IsNull(@LimitState2, -1);

		SELECT	TOP 1 @LimitState3 = AccessAllCode
		FROM	acc.tblAcntRng
		WHERE	(UserID = @UserID) AND (PartNumber = 3)

		SET @LimitState3 = IsNull(@LimitState3, -1);

		SELECT	TOP 1 @LimitState4 = AccessAllCode
		FROM	acc.tblAcntRng
		WHERE	(UserID = @UserID) AND (PartNumber = 4)

		SET @LimitState4 = IsNull(@LimitState4, -1);
	End

	if (@UseCurrency = 1)
		set @StrFrom = 'acc.vwVoucherDtl2'
	else
		set @StrFrom = 'acc.vwVoucherDtl'
	
	-------- LAYERS LEN CLAUSE -----------------------------------------------------------------------
	SELECT	@Part1Start = 1;
	SELECT	@Part1Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6 + Layer7 + Layer8 + Layer9 
	FROM	pub.tblCodeLayer 
	WHERE	(TableName = 'acc.tblAcnt') AND (PartNumber = 1)

	SELECT	@Part2Start = @Part1Start + @Part1Len + 1;
	SELECT	@Part2Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6 + Layer7 + Layer8 + Layer9 
	FROM	pub.tblCodeLayer 
	WHERE	(TableName = 'acc.tblAcnt') AND (PartNumber = 2)

	SELECT	@Part3Start = @Part2Start + @Part2Len + 1;
	SELECT	@Part3Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6 + Layer7 + Layer8 + Layer9 
	FROM	pub.tblCodeLayer 
	WHERE	(TableName = 'acc.tblAcnt') AND (PartNumber = 3)

	SELECT	@Part4Start = @Part3Start + @Part3Len + 1;
	SELECT	@Part4Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6 + Layer7 + Layer8 + Layer9 
	FROM	pub.tblCodeLayer 
	WHERE	(TableName = 'acc.tblAcnt') AND (PartNumber = 4)

	---- CALC LEN ----
	if @CustomerPartNo = 1
	Begin
		Set @CustomerPartStart	  = @Part1Start
		Set @CustomerPartLayerLen = @Part1Len
	End
	Else if @CustomerPartNo = 2
	Begin
		Set @CustomerPartStart	  = @Part2Start
		Set @CustomerPartLayerLen = @Part2Len
	End
	Else if @CustomerPartNo = 3
	Begin
		Set @CustomerPartStart    = @Part3Start
		Set @CustomerPartLayerLen = @Part3Len
	End
	Else if @CustomerPartNo = 4
	Begin
		Set @CustomerPartStart    = @Part4Start
		Set @CustomerPartLayerLen = @Part4Len
	End
		
	--===============	
	If @PartNo = 1
	Begin
		Set @iAcntStart = @Part1Start
		Set @iAcntLenW = 0
		Set @xLen = @Part1Len
	End
	Else If @PartNo = 2
	Begin
		Set @iAcntStart = @Part2Start
		Set @iAcntLenW = @Part1Start + @Part1Len - 1
		Set @xLen = @Part2Len
	End
	Else If @PartNo = 3
	Begin
		Set @iAcntStart = @Part3Start
		Set @iAcntLenW = @Part2Start + @Part2Len - 1
		Set @xLen = @Part3Len
	End
	Else If @PartNo = 4
	Begin
		Set @iAcntStart = @Part4Start
		Set @iAcntLenW = @Part3Start + @Part3Len - 1
		Set @xLen = @Part4Len
	End

	Set @xStart = @iAcntStart
	Set @iAcntLen = @PartLen
	
	-- Full Acnt Code Requested	
	If (@DistinctPart = 0) 
	Begin
		Set @iAcntLen = @iAcntStart + @PartLen - 1
		Set @iAcntStart = 1 
	End

	--=========================
	
	If  @CampaignID > 0 
		SET @StrAcntWhere = @StrAcntWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @CampaignID, 'CampaignID') 

	If  @VisitPathID1 > 0 
		SET @StrAcntWhere = @StrAcntWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @VisitPathID1, 'VisitPathID1') 
		
	If  @VisitPathID2 > 0 
		SET @StrAcntWhere = @StrAcntWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @VisitPathID2, 'VisitPathID2') 
		
	If  @VisitPathID3 > 0 
		SET @StrAcntWhere = @StrAcntWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @VisitPathID3, 'VisitPathID3') 
		
	If  @VisitPathID4 > 0 
		SET @StrAcntWhere = @StrAcntWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @VisitPathID4, 'VisitPathID4') 
		
	If @SalesRoomClass > 0 
		SET @StrAcntWhere = @StrAcntWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SalesRoomClass, 'SalesRoomClass') 
		
	If  @StrAcntWhere <> ''
		SET @StrAcntWhere = '
		INNER JOIN (Select AcntCode AcntC From acc.tblAcnt Where PartNumber = ' + LTrim(RTrim(Str(@CustomerPartNo))) + ' 
		'+  @StrAcntWhere +'
		) a 
		ON Cast(Substring(AcntCode, ' + LTrim(Str(@CustomerPartStart)) + ', ' + LTrim(Str(@CustomerPartLayerLen)) + ') AS VarChar(20)) = a.AcntC '
	--=========================
		
	--------  LAYERS LEN END  ---------------------------------------------------
	-------- CASE WHEN CLAUSE ---------------------------------------------------
	Declare @StrDebit	NVarChar(100);
	Declare @StrCredit	NVarChar(100);
	
	if (@DateFrom is not null)
	set @StrWhereDat = '(DocDate>=''' + @DateFrom + ''')'
	
	if (@SerialNoFrom is not null)
	set @StrWhereSrl = '(SerialNo>=' + LTrim(Str(@SerialNoFrom)) + ')'

	if (@OldSerialNoFrom is not null)
	begin
		if (@StrWhereSrl <> '')
		set @StrWhereSrl = @StrWhereSrl + ' and '
		set @StrWhereSrl = @StrWhereSrl + '(OldSerialNo>=' + LTrim(Str(@OldSerialNoFrom)) + ')'
	end
	
	If (@DateFrom Is Null)
	Begin
		-- DateFr = null
		If (@SerialNoFrom Is Null) and (@OldSerialNoFrom is null)
		Begin
			-- DateFr = null and SerialFr = null
			If (@PrimDocInRemain = 1)
			Begin
				SET @StrDebit  = 'CASE WHEN (VchKind<>2) THEN Debit  Else 0 End '
				SET @StrCredit = 'CASE WHEN (VchKind<>2) THEN Credit Else 0 End '
			End
			Else
			Begin	
				SET @StrDebit  = 'Debit '
				SET @StrCredit = 'Credit '
			End		
		End
		Else
		Begin
			-- DateFr = null and SerialFr <> null
			If (@PrimDocInRemain = 1)
			Begin
				SET @StrDebit   = 'CASE WHEN ' + @StrWhereSrl + ' AND (VchKind <> 2) THEN Debit  Else 0 End '
				SET @StrCredit  = 'CASE WHEN ' + @StrWhereSrl + ' AND (VchKind <> 2) THEN Credit Else 0 End '
			End
			Else
			Begin	
				SET @StrDebit   = 'CASE WHEN ' + @StrWhereSrl + ' THEN Debit  Else 0 End '
				SET @StrCredit  = 'CASE WHEN ' + @StrWhereSrl + ' THEN Credit Else 0 End '
			End
		End
	End
	Else
	Begin
		-- DateFr <> null
		If (@SerialNoFrom Is Null)
		Begin
			-- DateFr <> null and SerialFr = null
			Set @StrDebit   = 'CASE WHEN DocDate < ''' + @DateFrom + ''' THEN 0 Else Debit  End '
			Set @StrCredit  = 'CASE WHEN DocDate < ''' + @DateFrom + ''' THEN 0 Else Credit End '
		End
		Else
		Begin
			-- DateFr <> null and SerialFr <> null
			Set @StrDebit   = 'CASE WHEN ' + @StrWhereDat + ' AND ' + @StrWhereSrl + ' THEN Debit  Else 0 End '
			Set @StrCredit  = 'CASE WHEN ' + @StrWhereDat + ' AND ' + @StrWhereSrl + ' THEN Credit Else 0 End '
		End
	End
	------ CASE WHEN END -----------------------------------------------------

	------ WHERE CLAUSE ------------------------------------------------------
	Set @StrWhere = '(VchKind <> 0)'

	if (@CurrencyTypeID <> 'null') 
		set @StrWhere = @StrWhere + ' AND (CurrencyTypeID = ''' + @CurrencyTypeID + ''')'		

	if (@SharingDocs = 0)
		SET @StrWhere = @StrWhere + ' AND (SourceDocType <> 6)'

	declare @CodeLike as varchar(20)
	set @CodeLike = null;

	select	top 1 @CodeLike = AcntCode 
	from	acc.tblAcntSlc
	where	(PartNumber = 10) and
			(UserID = @UserID) and
			(ReportID = @ReportID) and
			(ObjectID = 10)

	if (@CodeLike is not null)
		SET @StrWhere = @StrWhere + ' AND (AcntCode LIKE ''' + RTrim(Replace(@CodeLike, ' ', '_')) + '%'')'
	
	if (@UseExtraCodes <> 1)
	begin
		declare @P1L1	int;

		select	@P1L1 = Layer1
		from	pub.tblCodeLayer 
		where	(TableName = 'acc.tblAcnt') AND (PartNumber = 1)

		Set @StrWhere = @StrWhere  + ' AND Substring(AcntCode, 1, ' + LTrim(Str(@P1L1)) + ') not in (select AcntCode from acc.tblAcnt where (PartNumber = 1) and (AcntType in (91,92)))'
	end

	If (@SourceProcessNo <> '0')
	BEGIN
		Declare @DistributionSourceProcessNo AS varchar(2)
		SET @DistributionSourceProcessNo = '0'
	
		SELECT @DistributionSourceProcessNo = SettingValue
		FROM pub.tblSettings
		WHERE SettingKey = 'DistributionSourceProcessNo'

		IF @DistributionSourceProcessNo<>'0' AND @DistributionSourceProcessNo=@SourceProcessNo
			SET @SourceProcessNo = @SourceProcessNo + ',10' 

		SET @StrWhere = @StrWhere  + ' AND ((IsAutoDoc = 0) OR SourceProcessNo IN (' + @SourceProcessNo + '))'
		--SET @StrWhere = @StrWhere  + ' AND (SourceProcessNo = ' + LTrim(STR(@SourceProcessNo)) + ')'
	END

	If (@ShowPrimary = 0)
	Set @StrWhere = @StrWhere  + ' AND VchKind <> 2 '

	If (@ShowFinish = 0)
	Set @StrWhere = @StrWhere  + ' AND VchKind <> 3 '

	If (@ShowClosed = 0)
	Set @StrWhere = @StrWhere  + ' AND VchKind <> 4 '
	
	If (@PartNo <> 1)
		If (@ShowAllCodes = 0) 
			Set @StrWhere = @StrWhere + ' AND Len(AcntCode) > ' + LTrim(Str(@iAcntLenW))
		--Else
		--	Set @StrWhere = @StrWhere + ' AND Len(AcntCode) >= ' + LTrim(Str(@iAcntLenW))

	-- Acnt1 --
	If (@AcntCode1From Is Not Null) AND (@AcntCode1To Is Not Null) AND (@AcntCode1From = @AcntCode1To)
		Set @StrWhere = @StrWhere + ' AND Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(Len(@AcntCode1From))) + ') = ''' + @AcntCode1From + ''''
	Else
	Begin
		If @AcntCode1From Is Not Null
			Set @StrWhere = @StrWhere + ' AND Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(Len(@AcntCode1From))) + ') >= ''' + @AcntCode1From + ''''
		If @AcntCode1To Is Not Null
			Set @StrWhere = @StrWhere + ' AND Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(Len(@AcntCode1To))) + ') <= ''' + @AcntCode1To + ''''
	End

	-- Acnt2 --
	If @AcntCode2From Is Not Null AND @AcntCode2To Is Not Null AND @AcntCode2From = @AcntCode2To
		Set @StrWhere = @StrWhere + ' AND Substring(AcntCode, ' + LTrim(Str(@Part2Start)) + ', ' + LTrim(Str(Len(@AcntCode2From))) + ') = ''' + @AcntCode2From + ''''
	Else
	Begin
		If @AcntCode2From Is Not Null
			Set @StrWhere = @StrWhere + ' AND Substring(AcntCode, ' + LTrim(Str(@Part2Start)) + ', ' + LTrim(Str(Len(@AcntCode2From))) + ') >= ''' + @AcntCode2From + ''''
		If @AcntCode2To Is Not Null
			Set @StrWhere = @StrWhere + ' AND Substring(AcntCode, ' + LTrim(Str(@Part2Start)) + ', ' + LTrim(Str(Len(@AcntCode2To))) + ') <= ''' + @AcntCode2To + ''''	
	End

