							(left(Substring(AcntCode, ' + LTrim(Str(@Part3Start)) + ', ' + LTrim(Str(@Part3Len)) + '), LEN(ToCode)) <= ToCode))= 0 '
	END
	
	IF @Part4Len>0
	BEGIN	
	If (@LimitState4 = -1)
