		Set @StrAcntCode = ' Space(' + LTrim(Str(@iAcntLenW + 1)) + ') + T.AcntCode'
	Else
		Set @StrAcntCode = 'T.AcntCode'
	
	if(@UseLastLayer=1)
	begin
		set @StrAcntName = 'acc.funGetLastPartName(' + @StrAcntCode + ')'
		--set @StrParentName = 'acc.funGetLastPartName(T.ParentCode)'
	end
	else
	begin
		set @StrAcntName = 'pub.GetCodeName(' + @StrAcntCode + ', 1)'
		--set @StrParentName = 'pub.GetCodeName(T.ParentCode, 1)'
	end
	
	set @StrParentName = '[acc].[funGetAcntFullName_LastLayers](T.ParentCode)'

	Set @StrSelect = '
		SELECT	Cast(T.AcntCode AS VarChar(20)) AS AcntCode, 
				Cast(T.ParentCode AS VarChar(20)) AS ParentCode, 
				Sum(Debit) SumDebit, Sum(Credit) SumCredit,
				case when (Sum(Debit)  - Sum(Credit))>0 then 
			ABS(Sum(Debit)  - Sum(Credit)) else 0 end DebitDif,
			case when  (Sum(Credit) - Sum(Debit) )>0 then 
	    	ABS(Sum(Credit) - Sum(Debit) ) else 0 end CreditDif, 
				' + @StrAcntName + ' AcntName,
				' + @StrParentName + ' ParentName,
				' + @StrDateGrp + ' 
		FROM (
			SELECT	Substring(AcntCode, ' + LTrim(Str(@iAcntStart)) + ', ' + LTrim(Str(@iAcntLen)) + ') AS AcntCode, 
					Substring(AcntCode, ' + LTrim(Str(@iAcntStart)) + ', ' + LTrim(Str(@ParentLen)) + ') AS ParentCode,
					Debit, Credit ' + @StrDateSel + '
			FROM	' + @StrFrom + ' ' + @StrAcntWhere + '
			WHERE   ' + @StrWhere
		if @Nosoon=1
			Set @StrSelect = @StrSelect + ' and Len(AcntCode) <= '+ LTrim(Str(@iAcntLen))  
	
	-- Zero Progress Included 
	If (@ZeroCycle = 1) AND (@PartNo = 1)
	Begin
		SET @StrSelect = @StrSelect  + ' 
			UNION ALL
			SELECT AcntCode, Left(AcntCode, ' + LTrim(Str(@ParentLen)) + ') ParentCode, 0 ,0 ' + @StrDateSelU + '
			FROM   acc.tblAcnt 
			WHERE  PartNumber = 1 AND Len(AcntCode) = ' + LTrim(Str(@PartLen)) 

		If (@UseSlcCodes = 1) AND (@StrWhereSLC <> '')
			SET @StrSelect = @StrSelect + @StrWhereSLC
			
	If (@AcntGroup Is Not Null) or (@AcntGroupTo <> 'null')
		SET @StrSelect = @StrSelect + ' 
			AND Substring(AcntCode, ' + LTrim(Str(@iAcntStart)) + ', ' + LTrim(Str(@iAcntLen)) + ')
			IN (
				SELECT	AcntCode 
				FROM	acc.tblAcntGroupsDocDtl
				WHERE	' + @StrWhereG + '
				)'

		-- Acnt1 --
		If @AcntCode1From Is Not Null AND @AcntCode1To Is Not Null AND @AcntCode1From = @AcntCode1To
			Set @StrSelect = @StrSelect + ' AND Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(Len(@AcntCode1From))) + ') = ''' + @AcntCode1From + ''''
		Else If @AcntCode1From Is Not Null
			Set @StrSelect = @StrSelect + ' AND Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(Len(@AcntCode1From))) + ') >= ''' + @AcntCode1From + ''''
		Else If @AcntCode1To Is Not Null
			Set @StrSelect = @StrSelect + ' AND Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(Len(@AcntCode1To))) + ') <= ''' + @AcntCode1To + ''''

		Set @StrSelect = @StrSelect + @StrWhere2
	End

	Set @StrSelect = @StrSelect + '
		) T	
		GROUP By T.AcntCode, ParentCode '

	If (@StrHaving <> '' )
	BEGIN
		Set @StrSelect = @StrSelect + '
		HAVING ' + @StrHaving;
	END

	select @AcntStart1=acc.funGetAcntLayerStartandLen(1,1)
	select @AcntLen1=acc.funGetAcntLayerStartandLen(1,2)

	select @AcntStart2=acc.funGetAcntLayerStartandLen(2,1)
	select @AcntLen2=acc.funGetAcntLayerStartandLen(2,2)

