	select @AcntLen3=acc.funGetAcntLayerStartandLen(3,2)

	select @AcntStart4=acc.funGetAcntLayerStartandLen(4,1)
select @AcntLen4=acc.funGetAcntLayerStartandLen(4,2)
		
	set @AcntCode1 = 'Substring(T.AcntCode, ' + LTrim(Str(@AcntStart1)) + ', ' + LTrim(Str(@AcntLen1)) +')'
	set @AcntCode2 = 'Substring(T.AcntCode, ' + LTrim(Str(@AcntStart2)) + ', ' + LTrim(Str(@AcntLen2)) +')'
	set @AcntCode3 = 'Substring(T.AcntCode, ' + LTrim(Str(@AcntStart3)) + ', ' + LTrim(Str(@AcntLen3)) +')'
	set @AcntCode4 = 'Substring(T.AcntCode, ' + LTrim(Str(@AcntStart4)) + ', ' + LTrim(Str(@AcntLen4)) +')'
	
	--------نام لایه های پارت اول----------------------------------------------------------------------------------------------------------------------------------------------
	select @Layer11=Layer1,	@Layer12=Layer2	,@Layer13=Layer3	,@Layer14=Layer4 from pub.tblCodeLayer where TableName='acc.tblAcnt' and PartNumber=1
	set @Layer12=@Layer11+@Layer12
	set @Layer13=@Layer13+@Layer12
	set @Layer14=@Layer13+@Layer14

	--------نام لایه های پارت اول----------------------------------------------------------------------------------------------------------------------------------------------
	select @Layer21=Layer1,	@Layer22=Layer2	,@Layer23=Layer3	,@Layer24=Layer4 from pub.tblCodeLayer where TableName='acc.tblAcnt' and PartNumber=2
	set @Layer22=@Layer21+@Layer22
	set @Layer23=@Layer23+@Layer22
	set @Layer24=@Layer23+@Layer24
	--------نام لایه های پارت اول----------------------------------------------------------------------------------------------------------------------------------------------
	select @Layer31=Layer1,	@Layer32=Layer2	,@Layer33=Layer3	,@Layer34=Layer4 from pub.tblCodeLayer where TableName='acc.tblAcnt' and PartNumber=3
	set @Layer32=@Layer31+@Layer32
	set @Layer33=@Layer33+@Layer32
	set @Layer34=@Layer33+@Layer34
		select @Layer41=Layer1,	@Layer42=Layer2	,@Layer43=Layer3	,@Layer44=Layer4 from pub.tblCodeLayer where TableName='acc.tblAcnt' and PartNumber=4
	set @Layer42=@Layer41+@Layer42
	set @Layer43=@Layer43+@Layer42
	set @Layer44=@Layer43+@Layer44
	------------------------------------------------------------------------------------------------------------------------------------------------------
	set @SqlLayer = @AcntCode1+' AcntCode1	,[acc].[funGetAcntName](' + @AcntCode1 + ',1 ,' + @LangID + ') AcntCode1Name 
	,'+@AcntCode2+' AcntCode2,[acc].[funGetAcntName](' + @AcntCode2 + ',2 ,' + @LangID + ') AcntCode2Name 
	,'+@AcntCode3+' AcntCode3,[acc].[funGetAcntName](' + @AcntCode3 + ',3 ,' + @LangID + ') AcntCode3Name 
	,'+@AcntCode4+' AcntCode4,[acc].[funGetAcntName](' + @AcntCode4 + ',4 ,' + @LangID + ') AcntCode4Name ,'

	set @SqlLayer=@SqlLayer+'	Cast(Substring(' + @AcntCode1 + ',1,'+str(@Layer11)+') as varchar(10)) Layer1,[acc].[funGetAcntName](Substring(' + @AcntCode1 + ',1,'+str(@Layer11)+'),1 ,' + @LangID + ') Layer1Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode1 + ',1,'+str(@Layer12)+') as varchar(10)) Layer2,[acc].[funGetAcntName](Substring(' + @AcntCode1 + ',1,'+str(@Layer12)+') ,1,' + @LangID + ') Layer2Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode1 + ',1,'+str(@Layer13)+') as varchar(10)) Layer3,[acc].[funGetAcntName](Substring(' + @AcntCode1 + ',1,'+str(@Layer13)+') ,1,' + @LangID + ') Layer3Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode1 + ',1,'+str(@Layer14)+') as varchar(10)) Layer4,[acc].[funGetAcntName](Substring(' + @AcntCode1 + ',1,'+str(@Layer14)+'),1 ,' + @LangID + ') Layer4Name ,'
	set @SqlLayer=@SqlLayer+'	Cast(Substring(' + @AcntCode2 + ',1,'+str(@Layer21)+') as varchar(10)) Layer21,[acc].[funGetAcntName](Substring(' + @AcntCode2 + ',1,'+str(@Layer21)+') ,2,' + @LangID + ') Layer21Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode2 + ',1,'+str(@Layer22)+') as varchar(10)) Layer22,[acc].[funGetAcntName](Substring(' + @AcntCode2 + ',1,'+str(@Layer22)+') ,2,' + @LangID + ') Layer22Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode2 + ',1,'+str(@Layer23)+') as varchar(10)) Layer23,[acc].[funGetAcntName](Substring(' + @AcntCode2 + ',1,'+str(@Layer23)+') ,2,' + @LangID + ') Layer23Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode2 + ',1,'+str(@Layer24)+') as varchar(10)) Layer24,[acc].[funGetAcntName](Substring(' + @AcntCode2 + ',1,'+str(@Layer24)+') ,2,' + @LangID + ') Layer24Name ,'
	set @SqlLayer=@SqlLayer+'	Cast(Substring(' + @AcntCode3 + ',1,'+str(@Layer31)+') as varchar(10)) Layer31,[acc].[funGetAcntName](Substring(' + @AcntCode3 + ',1,'+str(@Layer31)+'),3 ,' + @LangID + ') Layer31Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode3 + ',1,'+str(@Layer32)+') as varchar(10)) Layer32,[acc].[funGetAcntName](Substring(' + @AcntCode3 + ',1,'+str(@Layer32)+') ,3,' + @LangID + ') Layer32Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode3 + ',1,'+str(@Layer33)+') as varchar(10)) Layer33,[acc].[funGetAcntName](Substring(' + @AcntCode3 + ',1,'+str(@Layer33)+') ,3,' + @LangID + ') Layer33Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode3 + ',1,'+str(@Layer34)+') as varchar(10)) Layer34,[acc].[funGetAcntName](Substring(' + @AcntCode3 + ',1,'+str(@Layer34)+') ,3,' + @LangID + ') Layer34Name ,'
	set @SqlLayer=@SqlLayer+'	Cast(Substring(' + @AcntCode4 + ',1,'+str(@Layer41)+') as varchar(10)) Layer41,[acc].[funGetAcntName](Substring(' + @AcntCode4 + ',1,'+str(@Layer41)+') ,4,' + @LangID + ') Layer41Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode4 + ',1,'+str(@Layer42)+') as varchar(10)) Layer42,[acc].[funGetAcntName](Substring(' + @AcntCode4 + ',1,'+str(@Layer42)+'),4 ,' + @LangID + ') Layer42Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode4 + ',1,'+str(@Layer43)+') as varchar(10)) Layer43,[acc].[funGetAcntName](Substring(' + @AcntCode4 + ',1,'+str(@Layer43)+') ,4,' + @LangID + ') Layer43Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode4 + ',1,'+str(@Layer44)+') as varchar(10)) Layer44,[acc].[funGetAcntName](Substring(' + @AcntCode4 + ',1,'+str(@Layer44)+') ,4,' + @LangID + ') Layer44Name '

Set @StrSelect = 'SELECT  *,F.AccountNumber,F.ShabaAccountNumber,F.AcntComment AS AcntDesc, F.Address1 + F.Address2 AS AcntAddr,
				F.Tel, F.Mobile, F.Tel + ''--'' + pub.funGetLocationName (F.LocationID ,1)  AS AcntTelCity,'+ @SqlLayer +' 
 FROM (' + @StrSelect + ') T '+ 
'OUTER APPLY acc.funGetCodeInfo(' + @StrAcntCode + ') AS F '		

	If (@SortMode = 0 and @DistinctPart=1)
	   begin
		--Set @StrSelect = @StrSelect + '
		--ORDER By Sum(Credit)-Sum(Debit)'
		if (@SortCreDebMode= '1')
		begin
		 if(@SortAscDescMode = '1')
		 begin
		Set @StrSelect = @StrSelect + '
		ORDER By   CreditDif ASC ,DebitDif ASC '
		end
		else
		if(@SortAscDescMode = '2')
		 begin
		Set @StrSelect = @StrSelect + '
		ORDER By    DebitDif Desc,CreditDif DESC  '
		end
		end 
		 else 
		 	if (@SortCreDebMode='2')
		begin
		 
			 if(@SortAscDescMode = '1')
		 begin
		Set @StrSelect = @StrSelect + '
		ORDER By    DebitDif ASC ,CreditDif ASC '
		end
		else
		if(@SortAscDescMode = '2')
		 begin
		Set @StrSelect = @StrSelect + '
		ORDER By    CreditDif DESC ,DebitDif DESC  '
		end
		end 
			
		
		
		--if(@SortAscDescMode = '1')
		--Set @StrSelect = @StrSelect + '
		--ASC'
		--else
		--if(@SortAscDescMode = '2')
		--Set @StrSelect = @StrSelect + '
		--DESC'
	   end 
	   else
	   If (@SortMode = 0 and @DistinctPart=0)
	   begin
	   Set @StrSelect = @StrSelect + '
		ORDER By DebitDif DESC,CreditDif DESC '
	   end 
	Else If (@SortMode = 1)
		Set @StrSelect = @StrSelect + '
		ORDER By F.AcntName '
	Else
		Set @StrSelect = @StrSelect + '
		ORDER By T.AcntCode '

	print @StrSelect;	
	exec sp_executesql @StrSelect;
END

