		Else If (@LimitState1 = 0)
			Set @StrWhere2 = @StrWhere2 + '
				AND (SELECT	 IsNull(COUNT(*), 0)
					FROM	acc.tblAcntRng
					WHERE	(UserID = ' + LTRim(Str(@UserID)) + ') AND (PartNumber = 1) AND (AllowCodeView = 1) AND
							(LEFT(Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(@Part1Len)) + '), LEN(ToCode)) >= FromCode) AND 
							(LEFT(Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(@Part1Len)) + '), LEN(ToCode)) <= ToCode))> 0 '
			--AND acc.funPermitted(' + LTRim(Str(@UserID)) + ', Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(@Part1Len)) + '), 1)= 1 '
			
			
				 
			
		If (@UserIsAdmin <> 1) AND (SELECT COUNT(*) from acc.tblAcntRng WHERE AllowCodeView = 0 and PartNumber = 1 AND ((UserID = @UserID) or (UserID = -1)))>0
			Set @StrWhere2 = @StrWhere2 + '
				AND (SELECT	 IsNull(Count(*), 0)
