					 WHERE	((UserID = ' + LTRim(Str(@UserID)) + ') or (UserID = -1)) and
							(PartNumber = 1) and 
							(AllowCodeView = 0) and
							(left(Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(@Part1Len)) + '), LEN(ToCode)) >= FromCode) AND 
							(left(Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(@Part1Len)) + '), LEN(ToCode)) <= ToCode))= 0 '
		
