		If (@UserIsAdmin <> 1) AND (SELECT COUNT(*) from acc.tblAcntRng WHERE AllowCodeView = 0 and PartNumber = 3 AND ((UserID = @UserID) or (UserID = -1)))>0
			Set @StrWhere2 = @StrWhere2 + '
