	Begin
		If @StrHaving <> '' Set @StrHaving = @StrHaving + ' AND '
		Set @StrHaving = @StrHaving + '(Sum(DebitTotal)-Sum(Debit) <> Sum(CreditTotal)-Sum(Credit) OR Sum(DebitTotal) <> Sum(CreditTotal))'
	End	

	-- Debit From
	If (@DebitRemainFr <> -1)
	Begin
		If @StrHaving <> '' Set @StrHaving = @StrHaving + ' AND '
		Set @StrHaving = @StrHaving + 'Sum(DebitTotal) - Sum(CreditTotal) >= ' + LTrim(Str(@DebitRemainFr,20))
	End

	-- Debit To
	If (@DebitRemainTo <> -1)
	Begin
		If @StrHaving <> '' Set @StrHaving = @StrHaving + ' AND '
		Set @StrHaving = @StrHaving + 'Sum(DebitTotal) - Sum(CreditTotal) <= ' + LTrim(Str(@DebitRemainTo,20))
	End

	-- Credit From
	If (@CreditRemainFr <> -1)
	Begin
		If @StrHaving <> '' Set @StrHaving = @StrHaving + ' AND '
		Set @StrHaving = @StrHaving + 'Sum(CreditTotal) - Sum(DebitTotal) >= ' + LTrim(Str(@CreditRemainFr,20))
	End

	-- Credit To
	If (@CreditRemainTo <> -1)
	Begin
		If @StrHaving <> '' Set @StrHaving = @StrHaving + ' AND '
		Set @StrHaving = @StrHaving + 'Sum(CreditTotal) - Sum(DebitTotal) <= ' + LTrim(Str(@CreditRemainTo,20))
	End
	
	-- Debit Cycle From
	If (@DebitCycleFr <> -1)
	Begin
		If @StrHaving <> '' Set @StrHaving = @StrHaving + ' AND '
		Set @StrHaving = @StrHaving + 'Sum(Debit) >= ' + LTrim(Str(@DebitCycleFr,20))
	End

	-- Debit Cycle To
	If (@DebitCycleTo <> -1)
	Begin
		If @StrHaving <> '' Set @StrHaving = @StrHaving + ' AND '
		Set @StrHaving = @StrHaving + 'Sum(Debit) <= ' + LTrim(Str(@DebitCycleTo,20))
	End

	-- Credit Cycle From
	If (@CreditCycleFr <> -1)
	Begin
		If @StrHaving <> '' Set @StrHaving = @StrHaving + ' AND '
		Set @StrHaving = @StrHaving + 'Sum(Credit) >= ' + LTrim(Str(@CreditCycleFr,20))
	End

	-- Credit Cycle To
	If (@CreditCycleTo <> -1)
	Begin
		If @StrHaving <> '' Set @StrHaving = @StrHaving + ' AND '
		Set @StrHaving = @StrHaving + 'Sum(Credit) <= ' + LTrim(Str(@CreditCycleTo,20))
	End

	IF (@AcntName Is Not Null)
	Begin
		If @StrHaving <> '' Set @StrHaving = @StrHaving + ' AND '
		Set @StrHaving = @StrHaving + ' pub.GetCodeName(T.AcntCode, 1) LIKE N''%' + @AcntName + '%'' '
	End
	----- HAVING CLAUSE END -----------------------------------------------------

	--===== SELECT CLAUSE =======================================================
	Declare @StrAcntCode AS	NVarChar(100) 
	Declare @StrAcntName AS	NVarChar(500) 
	Declare @StrParentName AS NVarChar(500) 

	If (@DistinctPart = 1) AND (@PartNo > 1)
		Set @StrAcntCode = ' Space(' + LTrim(Str(@iAcntLenW + 1)) + ') + T.AcntCode'
	Else
		Set @StrAcntCode = 'T.AcntCode'

	if(@UseLastLayer=1)
	begin
		set @StrAcntName = 'acc.funGetLastPartName(' + @StrAcntCode + ')'
		--set @StrParentName = 'acc.funGetLastPartName(T.ParentCode)'
	end
	else
	begin
		set @StrAcntName = 'pub.GetCodeName(' + @StrAcntCode + ', 1)'
		--set @StrParentName = 'pub.GetCodeName(T.ParentCode, 1)'
	end

	set @StrParentName = '[acc].[funGetAcntFullName_LastLayers](T.ParentCode)'

	Set @StrSelect = '
		SELECT	Cast(T.AcntCode AS VarChar(20)) AS AcntCode, 
				Cast(T.ParentCode AS VarChar(20)) AS ParentCode, 
				Sum(Debit) SumDebit, Sum(Credit) SumCredit, 
				Sum(DebitTotal) SumDebitTotal, Sum(CreditTotal) SumCreditTotal,
					case when (Sum(DebitTotal)  - Sum(CreditTotal))>0 then 
			ABS(Sum(DebitTotal)  - Sum(CreditTotal)) else 0 end DebitDif,
			case when  (Sum(CreditTotal) - Sum(DebitTotal) )>0 then 
	    	ABS(Sum(CreditTotal)) - ABS(Sum(DebitTotal)) else 0 end CreditDif,  
				' + @StrAcntName + ' AcntName,
				' + @StrParentName + ' ParentName
		FROM (
			SELECT	Substring(AcntCode, ' + LTrim(Str(@iAcntStart)) + ', ' + LTrim(Str(@iAcntLen)) + ') AS AcntCode, 
					Substring(AcntCode, ' + LTrim(Str(@iAcntStart)) + ', ' + LTrim(Str(@ParentLen)) + ') AS ParentCode,' +
					@StrDebit + ' AS Debit, ' + @StrCredit + ' AS Credit, Debit AS DebitTotal, Credit AS CreditTotal 
			FROM	' + @StrFrom + ' ' + @StrAcntWhere  

	If (@StrWhere <> '')
		begin
		Set @StrSelect = @StrSelect + '
			WHERE ' + @StrWhere
		if @Nosoon=1
		Set @StrSelect = @StrSelect + ' and Len(AcntCode) <= '+ LTrim(Str(@iAcntLen))  
		end
		
	-- Zero Progress Included 
	If (@ZeroCycle = 1) AND (@PartNo = 1)
	Begin
		SET @StrSelect = @StrSelect  + ' 
			UNION ALL
			SELECT AcntCode, Left(AcntCode, ' + LTrim(Str(@ParentLen)) + ') ParentCode, 0, 0, 0, 0 
			FROM   acc.tblAcnt 
			WHERE  PartNumber = 1 AND Len(AcntCode) = ' + LTrim(Str(@PartLen)) 

		If (@UseSlcCodes = 1) AND (@StrWhereSLC <> '')
			SET @StrSelect = @StrSelect + @StrWhereSLC
			
	If (@AcntGroup Is Not Null) or (@AcntGroupTo <> 'null')
		SET @StrSelect = @StrSelect + ' 
			AND Substring(AcntCode, ' + LTrim(Str(@iAcntStart)) + ', ' + LTrim(Str(@iAcntLen)) + ')
			IN (
				SELECT	AcntCode 
				FROM	acc.tblAcntGroupsDocDtl
				WHERE	' + @StrWhereG + '
				)'

		-- Acnt1 --
		If @AcntCode1From Is Not Null AND @AcntCode1To Is Not Null AND @AcntCode1From = @AcntCode1To
			Set @StrSelect = @StrSelect + ' AND Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(Len(@AcntCode1From))) + ') = ''' + @AcntCode1From + ''''
		Else If @AcntCode1From Is Not Null
			Set @StrSelect = @StrSelect + ' AND Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(Len(@AcntCode1From))) + ') >= ''' + @AcntCode1From + ''''
		Else If @AcntCode1To Is Not Null
			Set @StrSelect = @StrSelect + ' AND Substring(AcntCode, ' + LTrim(Str(@Part1Start)) + ', ' + LTrim(Str(Len(@AcntCode1To))) + ') <= ''' + @AcntCode1To + ''''

		Set @StrSelect = @StrSelect + @StrWhere2
	End

	Set @StrSelect = @StrSelect + ') T
			
		GROUP By T.AcntCode, ParentCode '

	If (@StrHaving <> '')
		Set @StrSelect = @StrSelect + ' 
		HAVING ' + @StrHaving;

	select @AcntStart1=acc.funGetAcntLayerStartandLen(1,1)
	select @AcntLen1=acc.funGetAcntLayerStartandLen(1,2)

	select @AcntStart2=acc.funGetAcntLayerStartandLen(2,1)
	select @AcntLen2=acc.funGetAcntLayerStartandLen(2,2)

	select @AcntStart3=acc.funGetAcntLayerStartandLen(3,1)
	select @AcntLen3=acc.funGetAcntLayerStartandLen(3,2)

	select @AcntStart4=acc.funGetAcntLayerStartandLen(4,1)
	select @AcntLen4=acc.funGetAcntLayerStartandLen(4,2)

	
	set @AcntCode1 = 'Substring(T.AcntCode, ' + LTrim(Str(@AcntStart1)) + ', ' + LTrim(Str(@AcntLen1)) +')'
	set @AcntCode2 = 'Substring(T.AcntCode, ' + LTrim(Str(@AcntStart2)) + ', ' + LTrim(Str(@AcntLen2)) +')'
	set @AcntCode3 = 'Substring(T.AcntCode, ' + LTrim(Str(@AcntStart3)) + ', ' + LTrim(Str(@AcntLen3)) +')'
	set @AcntCode4 = 'Substring(T.AcntCode, ' + LTrim(Str(@AcntStart4)) + ', ' + LTrim(Str(@AcntLen4)) +')'
	
	--------نام لایه های پارت اول----------------------------------------------------------------------------------------------------------------------------------------------
	select @Layer11=Layer1,	@Layer12=Layer2	,@Layer13=Layer3	,@Layer14=Layer4 from pub.tblCodeLayer where TableName='acc.tblAcnt' and PartNumber=1
	set @Layer12=@Layer11+@Layer12
	set @Layer13=@Layer13+@Layer12
	set @Layer14=@Layer13+@Layer14

	--------نام لایه های پارت اول----------------------------------------------------------------------------------------------------------------------------------------------
	select @Layer21=Layer1,	@Layer22=Layer2	,@Layer23=Layer3	,@Layer24=Layer4 from pub.tblCodeLayer where TableName='acc.tblAcnt' and PartNumber=2
	set @Layer22=@Layer21+@Layer22
	set @Layer23=@Layer23+@Layer22
	set @Layer24=@Layer23+@Layer24
	--------نام لایه های پارت اول----------------------------------------------------------------------------------------------------------------------------------------------
	select @Layer31=Layer1,	@Layer32=Layer2	,@Layer33=Layer3	,@Layer34=Layer4 from pub.tblCodeLayer where TableName='acc.tblAcnt' and PartNumber=3
	set @Layer32=@Layer31+@Layer32
	set @Layer33=@Layer33+@Layer32
	set @Layer34=@Layer33+@Layer34
		select @Layer41=Layer1,	@Layer42=Layer2	,@Layer43=Layer3	,@Layer44=Layer4 from pub.tblCodeLayer where TableName='acc.tblAcnt' and PartNumber=4
	set @Layer42=@Layer41+@Layer42
	set @Layer43=@Layer43+@Layer42
	set @Layer44=@Layer43+@Layer44
	------------------------------------------------------------------------------------------------------------------------------------------------------
	set @SqlLayer = @AcntCode1+' AcntCode1	,[acc].[funGetAcntName](' + @AcntCode1 + ',1 ,' + @LangID + ') AcntCode1Name 
	,'+@AcntCode2+' AcntCode2,[acc].[funGetAcntName](' + @AcntCode2 + ',2 ,' + @LangID + ') AcntCode2Name 
	,'+@AcntCode3+' AcntCode3,[acc].[funGetAcntName](' + @AcntCode3 + ',3 ,' + @LangID + ') AcntCode3Name 
	,'+@AcntCode4+' AcntCode4,[acc].[funGetAcntName](' + @AcntCode4 + ',4 ,' + @LangID + ') AcntCode4Name ,'
		
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode1 + ',1,'+str(@Layer11)+') as varchar(10)) Layer1,[acc].[funGetAcntName](Substring(' + @AcntCode1 + ',1,'+str(@Layer11)+'),1 ,' + @LangID + ') Layer1Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode1 + ',1,'+str(@Layer12)+') as varchar(10)) Layer2,[acc].[funGetAcntName](Substring(' + @AcntCode1 + ',1,'+str(@Layer12)+') ,1,' + @LangID + ') Layer2Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode1 + ',1,'+str(@Layer13)+') as varchar(10)) Layer3,[acc].[funGetAcntName](Substring(' + @AcntCode1 + ',1,'+str(@Layer13)+') ,1,' + @LangID + ') Layer3Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode1 + ',1,'+str(@Layer14)+') as varchar(10)) Layer4,[acc].[funGetAcntName](Substring(' + @AcntCode1 + ',1,'+str(@Layer14)+'),1 ,' + @LangID + ') Layer4Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode2 + ',1,'+str(@Layer21)+') as varchar(10)) Layer21,[acc].[funGetAcntName](Substring(' + @AcntCode2 + ',1,'+str(@Layer21)+') ,2,' + @LangID + ') Layer21Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode2 + ',1,'+str(@Layer22)+') as varchar(10)) Layer22,[acc].[funGetAcntName](Substring(' + @AcntCode2 + ',1,'+str(@Layer22)+') ,2,' + @LangID + ') Layer22Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode2 + ',1,'+str(@Layer23)+') as varchar(10)) Layer23,[acc].[funGetAcntName](Substring(' + @AcntCode2 + ',1,'+str(@Layer23)+') ,2,' + @LangID + ') Layer23Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode2 + ',1,'+str(@Layer24)+') as varchar(10)) Layer24,[acc].[funGetAcntName](Substring(' + @AcntCode2 + ',1,'+str(@Layer24)+') ,2,' + @LangID + ') Layer24Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode3 + ',1,'+str(@Layer31)+') as varchar(10)) Layer31,[acc].[funGetAcntName](Substring(' + @AcntCode3 + ',1,'+str(@Layer31)+'),3 ,' + @LangID + ') Layer31Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode3 + ',1,'+str(@Layer32)+') as varchar(10)) Layer32,[acc].[funGetAcntName](Substring(' + @AcntCode3 + ',1,'+str(@Layer32)+') ,3,' + @LangID + ') Layer32Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode3 + ',1,'+str(@Layer33)+') as varchar(10)) Layer33,[acc].[funGetAcntName](Substring(' + @AcntCode3 + ',1,'+str(@Layer33)+') ,3,' + @LangID + ') Layer33Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode3 + ',1,'+str(@Layer34)+') as varchar(10)) Layer34,[acc].[funGetAcntName](Substring(' + @AcntCode3 + ',1,'+str(@Layer34)+') ,3,' + @LangID + ') Layer34Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode4 + ',1,'+str(@Layer41)+') as varchar(10)) Layer41,[acc].[funGetAcntName](Substring(' + @AcntCode4 + ',1,'+str(@Layer41)+') ,4,' + @LangID + ') Layer41Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode4 + ',1,'+str(@Layer42)+') as varchar(10)) Layer42,[acc].[funGetAcntName](Substring(' + @AcntCode4 + ',1,'+str(@Layer42)+'),4 ,' + @LangID + ') Layer42Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode4 + ',1,'+str(@Layer43)+') as varchar(10)) Layer43,[acc].[funGetAcntName](Substring(' + @AcntCode4 + ',1,'+str(@Layer43)+') ,4,' + @LangID + ') Layer43Name ,'
	set @SqlLayer= @SqlLayer+ ' Cast(Substring(' + @AcntCode4 + ',1,'+str(@Layer44)+') as varchar(10)) Layer44,[acc].[funGetAcntName](Substring(' + @AcntCode4 + ',1,'+str(@Layer44)+') ,4,' + @LangID + ') Layer44Name '
			
	Set @StrSelect = 'SELECT  *,F.AccountNumber,F.ShabaAccountNumber,F.AcntComment AS AcntDesc, F.Address1 + F.Address2 AS AcntAddr,
					F.Tel, F.Mobile, F.Tel + ''--'' + pub.funGetLocationName (F.LocationID ,1)  AS AcntTelCity,'+ @SqlLayer +' 
	 FROM (' + @StrSelect + ') T '+ 
	'OUTER APPLY acc.funGetCodeInfo(' + @StrAcntCode + ') AS F '

	If (@SortMode = 0  and @DistinctPart=1)
		   begin
		--Set @StrSelect = @StrSelect + '
		--ORDER By Sum(Credit)-Sum(Debit)'
		if (@SortCreDebMode= '1')
		begin
		 if(@SortAscDescMode = '1')
		 begin
		Set @StrSelect = @StrSelect + '
		ORDER By   CreditDif ASC ,DebitDif ASC '
		end
		else
		if(@SortAscDescMode = '2')
		 begin
		Set @StrSelect = @StrSelect + '
		ORDER By    DebitDif Desc,CreditDif DESC  '
		end
		end 
		 else 
		 	if (@SortCreDebMode='2')
		begin
		 
			 if(@SortAscDescMode = '1')
		 begin
		Set @StrSelect = @StrSelect + '
		ORDER By    DebitDif ASC ,CreditDif ASC '
		end
		else
		if(@SortAscDescMode = '2')
		 begin
		Set @StrSelect = @StrSelect + '
		ORDER By    CreditDif DESC ,DebitDif DESC  '
		end
		end 
			
		
		
		--if(@SortAscDescMode = '1')
		--Set @StrSelect = @StrSelect + '
		--ASC'
		--else
		--if(@SortAscDescMode = '2')
		--Set @StrSelect = @StrSelect + '
		--DESC'
		
	   end 
	   else
	   If (@SortMode = 0  and @DistinctPart=0)
		   begin
		  Set @StrSelect = @StrSelect + '
		ORDER By (SumCreditTotal - SumDebitTotal)'
	   end 
	   else
	   If (@SortMode = 0  and @DistinctPart=0)
		   begin
		    Set @StrSelect = @StrSelect + '
		ORDER By CreditDif '
		   end 
	Else If (@SortMode = 1)
		Set @StrSelect = @StrSelect + '
		ORDER By F.AcntName '
	Else
		Set @StrSelect = @StrSelect + '
		ORDER By AcntCode '
print @DistinctPart;
	print @StrSelect;	
	exec sp_executesql @StrSelect;
END

	CREATE PROCEDURE dbo.sp_helpdiagramdefinition
	(
		@diagramname 	sysname,
		@owner_id	int	= null 		
	)
	WITH EXECUTE AS N'dbo'
	AS
	BEGIN
		set nocount on

		declare @theId 		int
		declare @IsDbo 		int
		declare @DiagId		int
		declare @UIDFound	int
	
		if(@diagramname is null)
		begin
			RAISERROR (N'E_INVALIDARG', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner');
		if(@owner_id is null)
			select @owner_id = @theId;
		revert; 
	
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname;
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId ))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end

		select version, definition FROM dbo.sysdiagrams where diagram_id = @DiagId ; 
		return 0
	END

CREATE PROCEDURE dbo.sp_creatediagram
(
	@diagramname 	sysname,
	@owner_id		int	= null, 	
	@version 		int,
	@definition 	varbinary(max)
)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on

	declare @theId int
	declare @retval int
	declare @IsDbo	int
	declare @userName sysname
	if(@version is null or @diagramname is null)
	begin
		RAISERROR (N'E_INVALIDARG', 16, 1);
		return -1
	end

	execute as caller;
	select @theId = DATABASE_PRINCIPAL_ID(); 
	select @IsDbo = IS_MEMBER(N'db_owner');
	revert; 
	
	if @owner_id is null
	begin
		select @owner_id = @theId;
	end
	else
	begin
		if @theId <> @owner_id
		begin
			if @IsDbo = 0
			begin
				RAISERROR (N'E_INVALIDARG', 16, 1);
				return -1
			end
			select @theId = @owner_id
		end
	end
	-- next 2 line only for test, will be removed after define name unique
	if EXISTS(select diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @diagramname)
	begin
		RAISERROR ('The name is already used.', 16, 1);
		return -2
	end

	insert into dbo.sysdiagrams(name, principal_id , version, definition)
			VALUES(@diagramname, @theId, @version, @definition) ;
	
	select @retval = @@IDENTITY 
	return @retval
END

CREATE PROCEDURE dbo.sp_renamediagram
(
	@diagramname 		sysname,
	@owner_id		int	= null,
	@new_diagramname	sysname

)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on
	declare @theId 			int
	declare @IsDbo 			int
	
	declare @UIDFound 		int
	declare @DiagId			int
	declare @DiagIdTarg		int
	declare @u_name			sysname
	if((@diagramname is null) or (@new_diagramname is null))
	begin
		RAISERROR ('Invalid value', 16, 1);
		return -1
	end

	EXECUTE AS CALLER;
	select @theId = DATABASE_PRINCIPAL_ID();
	select @IsDbo = IS_MEMBER(N'db_owner'); 
	if(@owner_id is null)
		select @owner_id = @theId;
	REVERT;

	select @u_name = USER_NAME(@owner_id)

	select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
	if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
	begin
		RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
		return -3
	end

	-- if((@u_name is not null) and (@new_diagramname = @diagramname))	-- nothing will change
	--	return 0;

	if(@u_name is null)
		select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @new_diagramname
	else
		select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @owner_id and name = @new_diagramname

	if((@DiagIdTarg is not null) and  @DiagId <> @DiagIdTarg)
	begin
		RAISERROR ('The name is already used.', 16, 1);
		return -2
	end		

	if(@u_name is null)
		update dbo.sysdiagrams set [name] = @new_diagramname, principal_id = @theId where diagram_id = @DiagId
	else
		update dbo.sysdiagrams set [name] = @new_diagramname where diagram_id = @DiagId
	return 0
END

	CREATE PROCEDURE dbo.sp_alterdiagram
	(
		@diagramname 	sysname,
		@owner_id	int	= null,
		@version 	int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId 			int
		declare @retval 		int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
		declare @ShouldChangeUID	int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid ARG', 16, 1)
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();	 
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		revert;
	
		select @ShouldChangeUID = 0
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		
		if(@DiagId IS NULL or (@IsDbo = 0 and @theId <> @UIDFound))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end
	
		if(@IsDbo <> 0)
		begin
			if(@UIDFound is null or USER_NAME(@UIDFound) is null) -- invalid principal_id
			begin
				select @ShouldChangeUID = 1 ;
			end
		end

		-- update dds data			
		update dbo.sysdiagrams set definition = @definition where diagram_id = @DiagId ;

		-- change owner
		if(@ShouldChangeUID = 1)
			update dbo.sysdiagrams set principal_id = @theId where diagram_id = @DiagId ;

		-- update dds version
		if(@version is not null)
			update dbo.sysdiagrams set version = @version where diagram_id = @DiagId ;

		return 0
	END

CREATE PROCEDURE dbo.sp_dropdiagram
(
	@diagramname 	sysname,
	@owner_id	int	= null
)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on
	declare @theId 			int
	declare @IsDbo 			int
	
	declare @UIDFound 		int
	declare @DiagId			int

	if(@diagramname is null)
	begin
		RAISERROR ('Invalid value', 16, 1);
		return -1
	end

	EXECUTE AS CALLER;
	select @theId = DATABASE_PRINCIPAL_ID();
	select @IsDbo = IS_MEMBER(N'db_owner'); 
	if(@owner_id is null)
		select @owner_id = @theId;
	REVERT; 
	
	select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
