CREATE PROCEDURE [inv].[RptStore_SummaryEx]
	@ProcessID			Int = 90,
	@ProcessNo			Int = 10,
	@FiscalYearFr		Int = Null,
	@SerialNoFr			Int = Null,
	@FiscalYearTo		Int = Null,
	@SerialNoTo			Int = Null,
	@DocDateFr			Char(10) = Null,
	@DocDateTo			Char(10) = Null,
	@SelectedProds		Int = 0, 
	@SelectedGoods		Int = 0, 
	@SelectedStore		Int = 0, 
	@SelectedStor2		Int = 0, 
	@SelectedAcnt1		Int = 0, 
	@SelectedAcnt2		Int = 0, 
	@SelectedAcnt3		Int = 0, 
	@SelectedAcnt4		Int = 0, 
	@SelectedVisitor1	Int = 0, 
	@SelectedVisitor2	Int = 0, 
	@SelectedVisitor3	Int = 0, 
	@SelectedVisitor4	Int = 0, 
	@CustKind			VarChar(20) = null,
	@RepOptions			VarChar(20) = '1110011111', -- bit array options
	@SortFields			NVarChar(100) = Null,   -- Order By Field List
	@RepInfo			NVarChar(100) = '1@1@1'
--WITH ENCRYPTION
AS 
	---- Declarations ---------------
DECLARE @StrSelect	NVarChar(max);
DECLARE @StrFrom	NVarChar(max);
DECLARE @StrWhere	NVarChar(max);
DECLARE @StrWhereX	NVarChar(max);
DECLARE @StrWhereG	NVarChar(max);

DECLARE @DocStep	Int;

DECLARE @StrPrice	NVarChar(100);
DECLARE @EP			NVarChar(100);

DECLARE @ProcessID_Ret	Int;

DECLARE @ShowOverload	Bit;
DECLARE @ShowDiscount	Bit;  
DECLARE @DecReturn		Bit; -- Not Used; Only for Sync with summary report
DECLARE @UseAmount		Bit; -- Use Amount Field Instead of Price?
DECLARE @ZeroRows		Bit;
DECLARE @RefY			Bit;
DECLARE @RefN			Bit;

DECLARE	@LangID			Char(1);
DECLARE	@SessionNo		Int; -- برای حالت کدهای انتخابی
DECLARE	@ReportID		Int; -- برای حالت کدهای انتخابی

DECLARE @StrPID		nVarChar(50);
DECLARE @PID1	bit;
DECLARE @PID2	bit;
DECLARE @PID3	bit;

declare @StrQty		nvarchar(max);
declare @StrPrc		nvarchar(max);
declare @StrAtm		nvarchar(max);
declare @StrQtyR	nvarchar(max);
declare @StrPrcR	nvarchar(max);
declare @StrAtmR	nvarchar(max);
Begin --============== S T A R T  C O D E ===================================================

	SET NOCOUNT ON;

	-- Init Variables --------
	IF (@RepOptions Is Null)	SET @RepOptions = '1110111111'
	IF (@ProcessNo  Is Null)	SET @ProcessNo = 1;

	IF (@SelectedGoods	Is Null)	SET @SelectedGoods = 0;
	IF (@SelectedStore	Is Null)	SET @SelectedStore = 0;
	IF (@SelectedProds  Is Null)	SET @SelectedProds = 0;
	IF (@SelectedAcnt1	Is Null)	SET @SelectedAcnt1 = 0;
	IF (@SelectedAcnt2	Is Null)	SET @SelectedAcnt2 = 0;
	IF (@SelectedAcnt3	Is Null)	SET @SelectedAcnt3 = 0;
	IF (@SelectedAcnt4	Is Null)	SET @SelectedAcnt4 = 0;
	IF (@SelectedVisitor1 Is Null)	SET @SelectedVisitor1 = 0;
	IF (@SelectedVisitor2 Is Null)	SET @SelectedVisitor2 = 0;
	IF (@SelectedVisitor3 Is Null)	SET @SelectedVisitor3 = 0;
	IF (@SelectedVisitor4 Is Null)	SET @SelectedVisitor4 = 0;

	IF (@FiscalYearFr Is Null)		SET @SerialNoFr = Null;
	IF (@FiscalYearTo Is Null)		SET @SerialNoTo = Null;
	IF (@SerialNoFr	Is Null)		SET @FiscalYearFr = Null;
	IF (@SerialNoTo	Is Null)		SET @FiscalYearTo = Null;

	SET @DocStep		= Substring(@RepOptions, 1, 1);
	SET @ShowOverload	= Substring(@RepOptions, 2, 1);
	SET @ShowDiscount	= Substring(@RepOptions, 3, 1);
	SET @DecReturn		= Substring(@RepOptions, 4, 1);
	SET @UseAmount		= Substring(@RepOptions, 5, 1);
	SET @ZeroRows		= Substring(@RepOptions, 6, 1);
	SET @RefY			= Substring(@RepOptions, 7, 1);
	SET @RefN			= Substring(@RepOptions, 8, 1);
	SET @PID1			= Substring(@RepOptions, 9, 1);
	SET @PID2			= Substring(@RepOptions,10, 1);
	SET @PID3			= Substring(@RepOptions,11, 1);
	
	SET @LangID		= pub.funSplitString(@RepInfo, '@', 1);
	SET @SessionNo	= pub.funSplitString(@RepInfo, '@', 2);
	SET @ReportID	= pub.funSplitString(@RepInfo, '@', 3);

	SET @ProcessID_Ret =
		Case @ProcessID 
			When 55 Then 60
			When 70 Then 75
			When 90 Then 100
			When 110 Then 115
			Else 0
		End

	if (@PID1 = 0) and (@PID2 = 0) and (@PID3 = 0)
		set @PID1 = 1

	if (@ProcessID = 70) or (@ProcessID = 80)
	begin	
		set @StrPID = '0';

		if (@PID1 = 1)
			set @StrPID = @StrPID + ',' + ltrim(str(@ProcessID));

		if (@PID2 = 1)
			if (@ProcessID = 70) 
				set @StrPID = @StrPID + ',82' 
			else
				set @StrPID = @StrPID + ',72' 
			
		if (@PID3 = 1)
			if (@ProcessID = 70) 
				set @StrPID = @StrPID + ',83' 
			else
				set @StrPID = @StrPID + ',73' 
	end
	else
		set @StrPID = ltrim(str(@ProcessID))
	-- --------------------------------------------------
	-- Where Clause -----------------------------------------------------------
	Set @StrWhere = 'D.EnterKind<>0 AND (D.ProcessID in (' + @StrPID + '))'
	set @StrWhereG= '(1=1)'

	if not (@RefY = 1)
		set @StrWhere = @StrWhere + ' AND (D.BaseSerialNo=0)'
	if not (@RefN = 1)
		set @StrWhere = @StrWhere + ' AND (D.BaseSerialNo<>0)'

	if (@CustKind <> '')
		Set @StrWhere = @StrWhere + ' AND (pub.funGetCustomerKindID(D.AcntCode) = ''' + @CustKind + ''')'

	If (@ProcessNo Is Not Null) and (@ProcessNo > 0)
		SET @StrWhere = @StrWhere + ' AND (D.ProcessNo = ' + LTrim(Str(@ProcessNo)) + ')'

	If (@SerialNoFr Is Not Null)
		Set @StrWhere = @StrWhere + ' AND (D.FiscalYear > ' + LTrim(Str(@FiscalYearFr)) + ' OR (D.FiscalYear = ' + LTrim(Str(@FiscalYearFr)) + ' AND D.SerialNo >= ' + LTrim(Str(@SerialNoFr)) + '))' 
	If (@SerialNoTo Is Not Null)
		Set @StrWhere = @StrWhere + ' AND (D.FiscalYear < ' + LTrim(Str(@FiscalYearTo)) + ' OR (D.FiscalYear = ' + LTrim(Str(@FiscalYearTo)) + ' AND D.SerialNo <= ' + LTrim(Str(@SerialNoTo)) + '))' 

	IF (@DocDateFr Is Not Null)
		SET @StrWhere = @StrWhere + ' AND (D.DocDate >= ''' + @DocDateFr + ''')'
	IF @DocDateTo Is Not Null
		SET @StrWhere = @StrWhere + ' AND (D.DocDate <= ''' + @DocDateTo + ''')'

	If (@SelectedProds > 0)
		IF (@ProcessID = 80 Or @ProcessID = 85)
			SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedProds, 'D.GoodsID') 
		Else
			SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedProds, 'H.ProductID') 

	If (@SelectedGoods > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedGoods, 'D.GoodsID') 
	If (@SelectedStore > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedStore, 'D.StoreID') 
	If (@SelectedStor2 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedStor2, 'D.StoreID2')

	If (@SelectedAcnt1 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt1, 'D.AcntCode')
	If (@SelectedAcnt2 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt2, 'D.AcntCode')
	If (@SelectedAcnt3 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt3, 'D.AcntCode')
	If (@SelectedAcnt4 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt4, 'D.AcntCode')

	If (@SelectedVisitor1 > 0)
		SET @StrWhere = @StrWhere + ' AND (' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedVisitor1, 'H.VisitorAcntCode') + ')'
	If (@SelectedVisitor2 > 0)
		SET @StrWhere = @StrWhere + ' AND (' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedVisitor2, 'H.VisitorAcntCode') + ')'
	If (@SelectedVisitor3 > 0)
		SET @StrWhere = @StrWhere + ' AND (' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedVisitor3, 'H.VisitorAcntCode') + ')'
	If (@SelectedVisitor4 > 0)
		SET @StrWhere = @StrWhere + ' AND (' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedVisitor4, 'H.VisitorAcntCode') + ')'

	IF (@DocStep > 0)
		SET @StrWhere = @StrWhere + ' AND (D.DocStep = ' + LTrim(Str(@DocStep)) + ')'

	If (@SelectedGoods > 0)
		SET @StrWhereG = @StrWhereG + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedGoods, 'G.GoodsID') 
	---------------------------------------------------------
	-- Select Clause ----------------------------------------
	If (@UseAmount = 1) or (@ProcessID = 60)
		SET @StrPrice = 'GoodsAmount'
	Else 
		SET @StrPrice = 'GoodsPrice'
	
	SET @StrQty	= 'D.GoodsQuantity'
	SET @StrPrc	= '(D.GoodsQuantity * D.' + @StrPrice + ')'
	SET @StrAtm	= 'D.AtomAmount'
	SET @StrQtyR	= '0'
	SET @StrPrcR	= '0'
	SET @StrAtmR	= '0'

	IF (@DecReturn = 1) AND (@ProcessID_Ret <> 0) 
	BEGIN
		declare @WhrR nvarchar(max);
		set @WhrR = '(D2.ProcessID=' + str(@ProcessID_Ret) + ') AND (D2.ProcessNo=' + Str(@ProcessNo) + ') and (D2.GoodsID=D.GoodsID) AND (D2.BaseProcessID=D.ProcessID) AND (D2.BaseProcessNo=D.ProcessNo) AND (D2.BaseFiscalYear=D.FiscalYear) AND (D2.BaseSerialNo=D.SerialNo) AND (D2.BaseDocRowNo=D.DocRowNo)'
	
		SET @StrQtyR= 'isnull((SELECT SUM(D2.GoodsQuantity) FROM inv.tblStorageDocsDtl D2 WHERE ' + @WhrR + '),0)'
		SET @StrPrcR= 'isnull((SELECT SUM(D2.GoodsQuantity*D2.' + @StrPrice + ') FROM inv.tblStorageDocsDtl D2 WHERE ' + @WhrR + '),0)'
		SET @StrAtmR= 'isnull((SELECT SUM(D2.AtomAmount) FROM inv.tblStorageDocsDtl D2 WHERE ' + @WhrR + '),0)'
	END
	
	set @EP = 'Price-PriceR'

	if (@ShowOverload = 1)
		set @EP = @EP + '+Overload-OverloadR'
	if (@ShowDiscount = 1)
		set @EP = @EP + '-Discount '
		
	set @StrWhereX = '(1=1)'
	
	if (@ZeroRows = 0)
		set @StrWhereX= @StrWhereX + 'and ((SumQuantity01<>0)or(SumQuantity02<>0)or(SumQuantity03<>0)or(SumQuantity04<>0)or(SumQuantity05<>0)or(SumQuantity06<>0)or(SumQuantity07<>0)or(SumQuantity08<>0)or(SumQuantity09<>0)or(SumQuantity10<>0)or(SumQuantity11<>0)or(SumQuantity12<>0))'
	
	SET @StrSelect = '
	select	GoodsID, MonthCode, 
			Quantity-QuantityR as Quantity,
			(' + @EP + ') Price
	into #tbl_Store_SummaryEx_A
	from 
	(
		SELECT D.GoodsID, 
				' + @StrQty + ' Quantity,
				' + @StrPrc + ' Price,
				' + @StrAtm + ' Overload,
				' + @StrQtyR + ' QuantityR,
				' + @StrPrcR + ' PriceR,
				' + @StrAtmR + ' OverloadR,
				D.DiscountDtl Discount,
				Substring(D.DocDate, 6, 2) MonthCode
		FROM inv.tblStorageDocsDtl D 
				INNER JOIN inv.tblStorageDocsHdr H ON H.ProcessID=D.ProcessID AND H.ProcessNo=D.ProcessNo AND H.FiscalYear=D.FiscalYear AND H.SerialNo=D.SerialNo
		WHERE ' + @StrWhere + '
	) T 
	where (Quantity-QuantityR > 0) '
	
	SET @StrSelect = @StrSelect + '
	select	M.AvgPrice12,M.AvgPrice11,M.AvgPrice10,M.AvgPrice09,M.AvgPrice08,M.AvgPrice07,
			M.AvgPrice06,M.AvgPrice05,M.AvgPrice04,M.AvgPrice03,M.AvgPrice02,M.AvgPrice01,
			SumQuantity12,SumQuantity11,SumQuantity10,SumQuantity09,SumQuantity08,SumQuantity07,
			SumQuantity06,SumQuantity05,SumQuantity04,SumQuantity03,SumQuantity02,SumQuantity01,
			U.UnitName,G.GoodsName,M.GoodsID
	from
	(
		select G.GoodsID, G.UnitID,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''01'') SumQuantity01,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''02'') SumQuantity02,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''03'') SumQuantity03,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''04'') SumQuantity04,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''05'') SumQuantity05,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''06'') SumQuantity06,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''07'') SumQuantity07,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''08'') SumQuantity08,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''09'') SumQuantity09,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''10'') SumQuantity10,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''11'') SumQuantity11,
			(select isnull(Sum(A.Quantity),0)         from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''12'') SumQuantity12,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''01'') AvgPrice01,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''02'') AvgPrice02,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''03'') AvgPrice03,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''04'') AvgPrice04,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''05'') AvgPrice05,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''06'') AvgPrice06,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''07'') AvgPrice07,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''08'') AvgPrice08,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''09'') AvgPrice09,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''10'') AvgPrice10,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''11'') AvgPrice11,
			(select isnull(Sum(A.Price)/Sum(A.Quantity),0) from #tbl_Store_SummaryEx_A A where A.GoodsID=G.GoodsID and A.MonthCode=''12'') AvgPrice12
		from inv.tblGoods G
		Group By G.GoodsID, G.UnitID
	) M 
		inner join inv.tblGoodsDtl G on G.GoodsID= M.GoodsID
		left  join inv.tblUnitsDtl U on U.UnitID = M.UnitID	
	WHERE ' + @StrWhereX

	-- Sort Clause ---------------------------------------------
	If (@SortFields Is Not Null) AND (@SortFields <> '') 
	SET @StrSelect = @StrSelect + ' 
	ORDER BY ' + @SortFields
	------------------------------------------------------------
	-- Run -----------------------------------------------------
	print @StrSelect;
	Exec sp_executesql @StrSelect;
	------------------------------------------------------------
End

