CREATE FUNCTION [pub].[funLocationLayerName]
(
	@FullCode	VarChar(20),
	@Layer		int = 1
)
RETURNS NVarChar(250)
AS
Begin
declare @Table		varchar(20);
declare @Result		nvarchar(250);
declare @Start		int;
declare @Len		int;
declare @PartNo		int;

declare @Part1Start	int;
declare @Part2Start	int;
declare @Part3Start	int;
declare @Part4Start	int;
declare @Part1Len	int;
declare @Part2Len	int;
declare @Part3Len	int;
declare @Part4Len	int;

	set @Table = 'pub.tblLocations';
	set @PartNo	= 1;

	select	@Part1Start = 1;
	select	@Part1Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6 + Layer7 + Layer8 + Layer9 
	from	pub.tblCodeLayer 
	where	(TableName = @Table) AND (PartNumber = 1)

	select	@Part2Start = @Part1Start + @Part1Len + 1;
	select	@Part2Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6 + Layer7 + Layer8 + Layer9 
	from	pub.tblCodeLayer 
	where	(TableName = @Table) AND (PartNumber = 2)

	select	@Part3Start = @Part2Start + @Part2Len + 1;
	select	@Part3Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6 + Layer7 + Layer8 + Layer9 
	from	pub.tblCodeLayer 
	where	(TableName = @Table) AND (PartNumber = 3)

	select	@Part4Start = @Part3Start + @Part3Len + 1;
	select	@Part4Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6 + Layer7 + Layer8 + Layer9 
	from	pub.tblCodeLayer 
	where	(TableName = @Table) AND (PartNumber = 4)
	-------------------------------------------------------------
	if (@Layer = 1)
		select	@Len = Layer1
		from	pub.tblCodeLayer 
		where	(TableName = @Table) AND (PartNumber = @PartNo)
	if (@Layer = 2)
		select	@Len = Layer1 + Layer2
		from	pub.tblCodeLayer 
		where	(TableName = @Table) AND (PartNumber = @PartNo)
	if (@Layer = 3)
		select	@Len = Layer1 + Layer2 + Layer3
		from	pub.tblCodeLayer 
		where	(TableName = @Table) AND (PartNumber = @PartNo)
	if (@Layer = 4)
		select	@Len = Layer1 + Layer2 + Layer3 + Layer4
		from	pub.tblCodeLayer 
		where	(TableName = @Table) AND (PartNumber = @PartNo)
	if (@Layer = 5)
		select	@Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5
		from	pub.tblCodeLayer 
		where	(TableName = @Table) AND (PartNumber = @PartNo)
	if (@Layer = 6)
		select	@Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6
		from	pub.tblCodeLayer 
		where	(TableName = @Table) AND (PartNumber = @PartNo)
	if (@Layer = 7)
		select	@Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6 + Layer7
		from	pub.tblCodeLayer 
		where	(TableName = @Table) AND (PartNumber = @PartNo)
	if (@Layer = 8)
		select	@Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6 + Layer7 + Layer8
		from	pub.tblCodeLayer 
		where	(TableName = @Table) AND (PartNumber = @PartNo)
	if (@Layer = 9)
		select	@Len = Layer1 + Layer2 + Layer3 + Layer4 + Layer5 + Layer6 + Layer7 + Layer8 + Layer9 
		from	pub.tblCodeLayer 
		where	(TableName = @Table) AND (PartNumber = @PartNo)

	set @Start	= @Part1Start
	set @Len	= @Len

	if (@PartNo = 2)
		set @Start = @Part2Start

	if (@PartNo = 3)
		set @Start = @Part3Start

	if (@PartNo = 4)
		set @Start = @Part4Start

	set	@Result = '';

	select	@Result = LocationName
	from	pub.tblLocationsDtl
	where	LocationID = Substring(@FullCode, @Start, @Len) 

	return @Result
END

-- =========== TS-QC:UPDATED ====================
-- Author		 : TakroSystem\Ahmadnejad
-- Create date   : 1389/03/01
-- Viewed By	 : 
-- Last Modified : 
-- Last Modifier : 
-- Description	 : (S -> HM) تبدیل عدد ثانیه به رشته متنی ساعت و دقیقه
-- ===============================================
CREATE FUNCTION [pub].[funSecondToHM]
(
	@Seconds int
)
returns nvarchar(10)
as
begin
	declare @Result nvarchar(10)

    declare @intH	int;
    declare @intM	int;
    declare @intS	int;

	set @intH = 0;
	set @intM = 0;
	set @intS = 0;

    set @intH = @Seconds / 3600
    set @Seconds = @Seconds % 3600
    set @intM = @Seconds / 60


    if (@Seconds % 60) > 30 
       set @intM = @intM + 1
    
	set @Result = '';

	if (@intH < 10)
		set @Result = @Result + '0'

	set @Result = @Result + LTrim(Str(@intH));
	set @Result = @Result + ':'

	if (@intM < 10)
		set @Result = @Result + '0'

	set @Result = @Result + LTrim(Str(@intM));

	return @Result
END

