-- ======================================================= Select
-- ******************** Typ-1
	IF @RetType = 1
	BEGIN
		SET @StrSelect1 =
	   '
		SELECT ProcessID, 
			   ProcessNo, 
			   FiscalYear, 
			   SerialNo, 
			   DocRowNo, 
			   GoodsID,' +
			   CASE WHEN @DeductTax = 0 And @DeductDiscount = 0 THEN 'Sum(A.SalePrice - A.SameDateRetPrice - A.AfterSale_RetPrice - A.AfterSale_RetPrice2) '
			        WHEN @DeductTax = 0 And @DeductDiscount = 1 THEN 'Sum(A.SalePrice - A.SameDateRetPrice - A.AfterSale_RetPrice - A.AfterSale_RetPrice2) - Sum(A.SaleDiscountDtl) '
			        WHEN @DeductTax = 1 And @DeductDiscount = 0 THEN 'Sum(A.SalePrice - A.SameDateRetPrice - A.AfterSale_RetPrice - A.AfterSale_RetPrice2) + Sum(A.SaleTaxDtl) '
					ELSE 'Sum(A.SalePrice - A.SameDateRetPrice - A.AfterSale_RetPrice - A.AfterSale_RetPrice2) + Sum(A.SaleTaxDtl) - Sum(A.SaleDiscountDtl) ' END + '
		FROM(SELECT SD.ProcessID, 
					SD.ProcessNo, 
					SD.FiscalYear, 
					SD.SerialNo, 
					SD.DocRowNo, 
					SD.GoodsID,
					(ISNULL(SD.GoodsQuantity,0) * ISNULL(SD.GoodsPrice,0)) SalePrice, 
					ISNULL(SD.DiscountDtl,0) SaleDiscountDtl, 
					ISNULL(SH.TotalLineDiscount,0) SaleDiscount, 
					(ISNULL(SD.TaxOverWorthCostDtl,0) + ISNULL(SD.TollOverWorthCostDtl,0)) SaleTaxDtl,
					(ISNULL(Ret1.GoodsQuantity,0) * ISNULL(Ret1.GoodsPrice,0)) SameDateRetPrice, 
					ISNULL(Ret1.DiscountDtl,0) SameDateRetDiscountDtl, 
					ISNULL(Ret1.TotalLineDiscount,0) SameDateRetDiscount, 
					(ISNULL(Ret2.GoodsQuantity,0) * ISNULL(Ret2.GoodsPrice,0)) AfterSale_RetPrice, 
					ISNULL(Ret2.DiscountDtl,0) AfterSale_RetDiscountDtl, 
					ISNULL(Ret2.TotalLineDiscount,0) AfterSale_RetDiscount,
					(ISNULL(Ret3.GoodsQuantity,0) * ISNULL(Ret3.GoodsPrice,0)) AfterSale_RetPrice2, 
					ISNULL(Ret3.DiscountDtl,0) AfterSale_RetDiscountDtl2, 
					ISNULL(Ret3.TotalLineDiscount,0) AfterSale_RetDiscount2,
					(ISNULL(SD.GoodsQuantity,0) - ISNULL(Ret1.GoodsQuantity,0) - ISNULL(Ret2.GoodsQuantity,0)) NetSaleQty 
			 From inv.tblStorageDocsDtl SD
			 INNER JOIN inv.tblStorageDocsHdr SH ON SH.ProcessID = SD.ProcessID 
												AND SH.ProcessNo = SD.ProcessNo 
												AND SH.FiscalYear = SD.FiscalYear 
												AND SH.SerialNo = SD.SerialNo 
			 LEFT JOIN (SELECT RD1.*, 
							   RH1.TotalLineDiscount 
						FROM inv.tblStorageDocsDtl RD1 
						INNER JOIN inv.tblStorageDocsHdr RH1 ON RH1.ProcessID = RD1.ProcessID 
															AND RH1.ProcessNo = RD1.ProcessNo 
															AND RH1.FiscalYear = RD1.FiscalYear 
															AND RH1.SerialNo = RD1.SerialNo
						WHERE RD1.ProcessID = 100 
						  AND (' + LTRIM(RTrim(Str(@ProcessNo))) + ' = 0 OR RD1.ProcessNo = ' + LTRIM(RTrim(Str(@ProcessNo))) + ')) Ret1 ON	Ret1.BaseProcessID = SD.ProcessID 
																																		AND Ret1.BaseProcessNo = SD.ProcessNo 
																																		AND Ret1.BaseFiscalYear = SD.FiscalYear 
																																		AND Ret1.BaseSerialNo = SD.SerialNo 
																																		AND Ret1.BaseDocRowNo = SD.DocRowNo 
																																		AND Ret1.DocDate = SD.DocDate
			 LEFT JOIN (SELECT RD1.*, 
							   RH1.TotalLineDiscount 
						FROM inv.tblStorageDocsDtl RD1 
						INNER JOIN inv.tblStorageDocsHdr RH1 ON RH1.ProcessID = RD1.ProcessID 
															AND RH1.ProcessNo = RD1.ProcessNo 
															AND RH1.FiscalYear = RD1.FiscalYear 
															AND RH1.SerialNo  = RD1.SerialNo
						WHERE RD1.ProcessID = 100 
						  AND (' + LTRIM(RTrim(Str(@ProcessNo))) + ' = 0 OR RD1.ProcessNo = ' + LTRIM(RTrim(Str(@ProcessNo))) + ')) Ret2 ON	Ret2.BaseProcessID = SD.ProcessID 
																																		AND Ret2.BaseProcessNo = SD.ProcessNo 
																																		AND Ret2.BaseFiscalYear = SD.FiscalYear 
																																		AND Ret2.BaseSerialNo = SD.SerialNo 
																																		AND Ret2.BaseDocRowNo = SD.DocRowNo   
																																		AND Ret2.DocDate > SD.DocDate 
						' + @StrWhereAfteSale_Rets
		SET @StrSelect2 =
		   ' Left Join (SELECT RD1.*, 
							   RH1.TotalLineDiscount 
						FROM inv.tblStorageDocsDtl RD1 
						INNER JOIN inv.tblStorageDocsHdr RH1 ON RH1.ProcessID = RD1.ProcessID 
															AND RH1.ProcessNo = RD1.ProcessNo 
															AND RH1.FiscalYear = RD1.FiscalYear 
															AND RH1.SerialNo = RD1.SerialNo
						WHERE RD1.ProcessID = 100 
						  AND (' + LTRIM(RTrim(Str(@ProcessNo))) + ' = 0 OR RD1.ProcessNo = ' + LTRIM(RTrim(Str(@ProcessNo))) + ')) Ret3 ON	Ret3.BaseProcessID = SD.ProcessID 
																																		AND Ret3.BaseProcessNo = SD.ProcessNo 
																																		AND Ret3.BaseFiscalYear = SD.FiscalYear 
																																		AND Ret3.BaseSerialNo = SD.SerialNo 
																																		AND Ret3.BaseDocRowNo = SD.DocRowNo 
						' + @StrWhereAfteSale_RetsNoLimit + '
			 WHERE ' + @StrWhere + ' ) A
			 GROUP BY ProcessID, ProcessNo, FiscalYear, SerialNo, DocRowNo, GoodsID	
		'
	END
	
-- ******************** Typ-2
	IF @RetType = 2
	BEGIN
		SET @StrSelect1 =  
'		
		SELECT ProcessID, 
			   ProcessNo, 
			   FiscalYear, 
			   SerialNo, 
			   DocRowNo, 
			   GoodsID,
			   ISNULL(SUM(' +
			   CASE WHEN @DeductTax = 0 And @DeductDiscount = 0 THEN 'A.SameDateRetPrice '
			        WHEN @DeductTax = 0 And @DeductDiscount = 1 THEN 'A.SameDateRetPrice - A.SameDateRetDiscountDtl '
			        WHEN @DeductTax = 1 And @DeductDiscount = 0 THEN 'A.SameDateRetPrice + A.SameDateRetTaxDtl  '
					ELSE 'A.SameDateRetPrice - A.SameDateRetDiscountDtl + A.SameDateRetTaxDtl ' END + '),0) SameDateRetPrice
		FROM(SELECT SD.ProcessID, 
					SD.ProcessNo, 
					SD.FiscalYear, 
					SD.SerialNo, 
					SD.DocRowNo, 
					SD.GoodsID,
					(ISNULL(Ret1.GoodsQuantity,0) * ISNULL(Ret1.GoodsPrice,0)) SameDateRetPrice,
					ISNULL(Ret1.DiscountDtl,0) SameDateRetDiscountDtl,
					(ISNULL(Ret1.TaxOverWorthCostDtl,0) + ISNULL(Ret1.TollOverWorthCostDtl,0)) SameDateRetTaxDtl,
					ISNULL(Ret1.TotalLineDiscount,0) SameDateRetDiscount 
			 FROM inv.tblStorageDocsDtl SD
			 INNER JOIN inv.tblStorageDocsHdr SH ON SH.ProcessID = SD.ProcessID 
												AND SH.ProcessNo = SD.ProcessNo 
												AND SH.FiscalYear = SD.FiscalYear 
												AND SH.SerialNo = SD.SerialNo
			 -- SameDateRets
			 LEFT JOIN (SELECT RD1.*, 
							   RH1.TotalLineDiscount 
						FROM inv.tblStorageDocsDtl RD1 
						INNER JOIN inv.tblStorageDocsHdr RH1 ON RH1.ProcessID = RD1.ProcessID  
															AND RH1.ProcessNo = RD1.ProcessNo 
															AND RH1.FiscalYear = RD1.FiscalYear 
															AND RH1.SerialNo = RD1.SerialNo 
						WHERE RD1.ProcessID = 100 
						  AND (' + LTRIM(RTrim(Str(@ProcessNo))) + ' = 0 OR RD1.ProcessNo = ' + LTRIM(RTrim(Str(@ProcessNo))) + ')) Ret1 ON	Ret1.BaseProcessID = SD.ProcessID 
																																		AND Ret1.BaseProcessNo = SD.ProcessNo 
																																		AND Ret1.BaseFiscalYear = SD.FiscalYear 
																																		AND Ret1.BaseSerialNo = SD.SerialNo 
																																		AND Ret1.BaseDocRowNo = SD.DocRowNo 
																																		AND Ret1.DocDate = SD.DocDate
		WHERE ' + @StrWhere + ' ) A
		GROUP BY ProcessID, ProcessNo, FiscalYear, SerialNo, DocRowNo, GoodsID	
		 '
	END
		
-- ******************** Typ-3
	IF @RetType = 3
	BEGIN
		SET @StrSelect1 = 
'	
		SELECT ProcessID, 
			   ProcessNo, 
			   FiscalYear, 
			   SerialNo, 
			   DocRowNo, 
			   GoodsID, 
			   ISNULL(SUM(' +
			   CASE WHEN @DeductTax = 0 And @DeductDiscount = 0 THEN 'A.AfterSale_RetPrice '
			        WHEN @DeductTax = 0 And @DeductDiscount = 1 THEN 'A.AfterSale_RetPrice - A.AfterSale_RetDiscountDtl '
			        WHEN @DeductTax = 1 And @DeductDiscount = 0 THEN 'A.AfterSale_RetPrice + A.AfterSale_RetTaxDtl  '
					ELSE 'A.AfterSale_RetPrice - A.AfterSale_RetDiscountDtl + A.AfterSale_RetTaxDtl ' END + '),0) AfterSale_Rets
		FROM(SELECT SD.ProcessID, 
					SD.ProcessNo, 
					SD.FiscalYear, 
					SD.SerialNo, 
					SD.DocRowNo, 
					SD.GoodsID,
					(ISNULL(SD.GoodsQuantity,0) * ISNULL(SD.GoodsPrice,0)) SalePrice, 
					ISNULL(SD.DiscountDtl,0) SaleDiscountDtl, 
					ISNULL(SH.TotalLineDiscount,0) SaleDiscount,
					(ISNULL(Ret2.GoodsQuantity,0) * ISNULL(Ret2.GoodsPrice,0)) AfterSale_RetPrice, 
					ISNULL(Ret2.DiscountDtl,0) AfterSale_RetDiscountDtl, 
					(ISNULL(Ret2.TaxOverWorthCostDtl,0) + ISNULL(Ret2.TollOverWorthCostDtl,0)) AfterSale_RetTaxDtl,
					ISNULL(Ret2.TotalLineDiscount,0) AfterSale_RetDiscount				   	   
			 FROM inv.tblStorageDocsDtl SD
			 INNER JOIN inv.tblStorageDocsHdr SH ON SH.ProcessID = SD.ProcessID 
												AND SH.ProcessNo = SD.ProcessNo 
												AND SH.FiscalYear = SD.FiscalYear 
												AND SH.SerialNo = SD.SerialNo 
			 LEFT JOIN (SELECT RD1.*, 
							   RH1.TotalLineDiscount 
						FROM inv.tblStorageDocsDtl RD1 
						INNER JOIN inv.tblStorageDocsHdr RH1 ON RH1.ProcessID = RD1.ProcessID 
															AND RH1.ProcessNo = RD1.ProcessNo 
															AND RH1.FiscalYear = RD1.FiscalYear 
															AND RH1.SerialNo  = RD1.SerialNo
						WHERE RD1.ProcessID = 100 
						  And (' + LTRIM(RTrim(Str(@ProcessNo))) + ' = 0 OR RD1.ProcessNo = ' + LTRIM(RTrim(Str(@ProcessNo))) + ')) Ret2 ON	Ret2.BaseProcessID = SD.ProcessID 
																																		AND Ret2.BaseProcessNo = SD.ProcessNo 
																																		AND Ret2.BaseFiscalYear = SD.FiscalYear 
																																		AND Ret2.BaseSerialNo = SD.SerialNo 
																																		AND Ret2.BaseDocRowNo = SD.DocRowNo 
																																		AND Ret2.DocDate > SD.DocDate 
						' + @StrWhereAfteSale_Rets + '
		Where ' + @StrWhere + ' ) A
		GROUP BY ProcessID, ProcessNo, FiscalYear, SerialNo, DocRowNo, GoodsID	
		 '
	END
		
-- ******************** Typ-4
	IF @RetType = 4
	BEGIN
		SET @StrSelect1 = 
'		
		SELECT ProcessID, 
			   ProcessNo, 
			   FiscalYear, 
			   SerialNo, 
			   DocRowNo, 
			   GoodsID, 
			   ISNULL(SUM(' +
			   CASE WHEN @DeductTax = 0 And @DeductDiscount = 0 THEN 'A.AfterSale_RetPrice '
			        WHEN @DeductTax = 0 And @DeductDiscount = 1 THEN 'A.AfterSale_RetPrice - A.AfterSale_RetDiscountDtl '
			        WHEN @DeductTax = 1 And @DeductDiscount = 0 THEN 'A.AfterSale_RetPrice + A.AfterSale_RetTaxDtl  '
					ELSE 'A.AfterSale_RetPrice - A.AfterSale_RetDiscountDtl + A.AfterSale_RetTaxDtl ' END + '),0) AfterSale_RetsNoDateLimit 
		FROM(SELECT SD.ProcessID, 
					SD.ProcessNo, 
					SD.FiscalYear, 
					SD.SerialNo, 
					SD.DocRowNo, 
					SD.GoodsID,
					(ISNULL(SD.GoodsQuantity,0) * ISNULL(SD.GoodsPrice,0)) SalePrice, 
					ISNULL(SD.DiscountDtl,0) SaleDiscountDtl, 
					ISNULL(SH.TotalLineDiscount,0) SaleDiscount,
					(ISNULL(Ret2.GoodsQuantity,0) * ISNULL(Ret2.GoodsPrice,0)) AfterSale_RetPrice, 
					ISNULL(Ret2.DiscountDtl,0) AfterSale_RetDiscountDtl, 
					(ISNULL(Ret2.TaxOverWorthCostDtl,0) + ISNULL(Ret2.TollOverWorthCostDtl,0)) AfterSale_RetTaxDtl,
					ISNULL(Ret2.TotalLineDiscount,0) AfterSale_RetDiscount 
			 FROM inv.tblStorageDocsDtl SD
			 INNER JOIN inv.tblStorageDocsHdr SH ON SH.ProcessID = SD.ProcessID 
												AND SH.ProcessNo = SD.ProcessNo 
												AND SH.FiscalYear = SD.FiscalYear 
												AND SH.SerialNo = SD.SerialNo 
			 LEFT JOIN (SELECT RD1.*, 
							   RH1.TotalLineDiscount 
						FROM inv.tblStorageDocsDtl RD1 
						INNER JOIN inv.tblStorageDocsHdr RH1 ON RH1.ProcessID = RD1.ProcessID 
															AND RH1.ProcessNo = RD1.ProcessNo 
															AND RH1.FiscalYear = RD1.FiscalYear 
															AND RH1.SerialNo  = RD1.SerialNo
						 WHERE RD1.ProcessID = 100 
						   AND (' + LTRIM(RTrim(Str(@ProcessNo))) + ' = 0 OR RD1.ProcessNo = ' + LTRIM(RTrim(Str(@ProcessNo))) + ')) Ret2 ON Ret2.BaseProcessID = SD.ProcessID 
																																		 And Ret2.BaseProcessNo = SD.ProcessNo 
																																		 And Ret2.BaseFiscalYear = SD.FiscalYear 
																																		 And Ret2.BaseSerialNo = SD.SerialNo 
																																		 And Ret2.BaseDocRowNo = SD.DocRowNo   
			' + @StrWhereAfteSale_RetsNoLimit + '
		WHERE ' + @StrWhere + ' ) A
		GROUP BY ProcessID, ProcessNo, FiscalYear, SerialNo, DocRowNo, GoodsID
		'
	END
		
-- ******************** Typ-5
	IF @RetType = 5
	BEGIN
		SET @StrSelect1 = '
		SELECT ProcessID, 
			   ProcessNo, 
			   FiscalYear, 
			   SerialNo, 
			   DocRowNo, 
			   GoodsID, 
			   ISNULL(SUM(' +
			   CASE WHEN @DeductTax = 0 And @DeductDiscount = 0 THEN 'A.SameDateRetPrice + A.AfterSale_RetPrice '
			        WHEN @DeductTax = 0 And @DeductDiscount = 1 THEN '(A.AfterSale_RetPrice - A.AfterSale_RetDiscountDtl) + (A.SameDateRetPrice - A.SameDateRetDiscountDtl) + (A.AfterSale_RetPrice2 - A.AfterSale_RetDiscountDtl2) '
			        WHEN @DeductTax = 1 And @DeductDiscount = 0 THEN '(A.AfterSale_RetPrice + A.AfterSale_RetTaxDtl) + (A.SameDateRetPrice + A.SameDateRetTaxDtl) + (A.AfterSale_RetPrice2 + A.AfterSale_RetTaxDtl2) '
					ELSE '(A.AfterSale_RetPrice - A.AfterSale_RetDiscountDtl + A.AfterSale_RetTaxDtl) + 
						  (A.SameDateRetPrice - A.SameDateRetDiscountDtl + A.SameDateRetTaxDtl) + 
						  (A.AfterSale_RetPrice2 - A.AfterSale_RetDiscountDtl2 + A.AfterSale_RetTaxDtl2)  ' END + '),0)
		FROM(Select SD.ProcessID, 
					SD.ProcessNo, 
					SD.FiscalYear, 
					SD.SerialNo, 
					SD.DocRowNo, 
					SD.GoodsID,
					(ISNULL(SD.GoodsQuantity,0) * ISNULL(SD.GoodsPrice,0)) SalePrice, 
					ISNULL(SD.DiscountDtl,0) SaleDiscountDtl, 
					ISNULL(SH.TotalLineDiscount,0) SaleDiscount,
					(ISNULL(Ret1.GoodsQuantity,0) * ISNULL(Ret1.GoodsPrice,0)) SameDateRetPrice, 
					ISNULL(Ret1.DiscountDtl,0) SameDateRetDiscountDtl, 
					(ISNULL(Ret1.TaxOverWorthCostDtl,0) + ISNULL(Ret1.TollOverWorthCostDtl,0)) SameDateRetTaxDtl, 
					ISNULL(Ret1.TotalLineDiscount,0) SameDateRetDiscount,
					(ISNULL(Ret2.GoodsQuantity,0) * ISNULL(Ret2.GoodsPrice,0)) AfterSale_RetPrice, 
					ISNULL(Ret2.DiscountDtl,0) AfterSale_RetDiscountDtl, 
					(ISNULL(Ret2.TaxOverWorthCostDtl,0) + ISNULL(Ret2.TollOverWorthCostDtl,0)) AfterSale_RetTaxDtl, 
					ISNULL(Ret2.TotalLineDiscount,0) AfterSale_RetDiscount,
					(ISNULL(Ret3.GoodsQuantity,0) * ISNULL(Ret3.GoodsPrice,0)) AfterSale_RetPrice2, 
					ISNULL(Ret3.DiscountDtl,0) AfterSale_RetDiscountDtl2, 
					(ISNULL(Ret3.TaxOverWorthCostDtl,0) + ISNULL(Ret3.TollOverWorthCostDtl,0)) AfterSale_RetTaxDtl2, 
					ISNULL(Ret3.TotalLineDiscount,0) AfterSale_RetDiscount2,
					(ISNULL(SD.GoodsQuantity,0) - ISNULL(Ret1.GoodsQuantity,0) - ISNULL(Ret2.GoodsQuantity,0)) NetSaleQty
			 FROM inv.tblStorageDocsDtl SD
			 INNER JOIN inv.tblStorageDocsHdr SH ON SH.ProcessID = SD.ProcessID  
												And SH.ProcessNo = SD.ProcessNo 
												And SH.FiscalYear = SD.FiscalYear 
												And SH.SerialNo  = SD.SerialNo 
			 LEFT JOIN (SELECT RD1.*, 
							   RH1.TotalLineDiscount
						FROM inv.tblStorageDocsDtl RD1 
						INNER JOIN inv.tblStorageDocsHdr RH1 ON RH1.ProcessID = RD1.ProcessID  
															AND RH1.ProcessNo = RD1.ProcessNo 
															AND RH1.FiscalYear = RD1.FiscalYear 
															AND RH1.SerialNo  = RD1.SerialNo
						WHERE RD1.ProcessID = 100 
						  AND (' + LTRIM(RTrim(Str(@ProcessNo))) + ' = 0 OR RD1.ProcessNo = ' + LTRIM(RTrim(Str(@ProcessNo))) + ')) Ret1 ON	Ret1.BaseProcessID = SD.ProcessID 
																																		AND Ret1.BaseProcessNo = SD.ProcessNo 
																																		AND Ret1.BaseFiscalYear = SD.FiscalYear 
																																		AND Ret1.BaseSerialNo = SD.SerialNo 
																																		AND Ret1.BaseDocRowNo = SD.DocRowNo 
																																		AND Ret1.DocDate = SD.DocDate
			 LEFT JOIN (SELECT RD1.*, 
							   RH1.TotalLineDiscount 
						FROM inv.tblStorageDocsDtl RD1 
						INNER JOIN inv.tblStorageDocsHdr RH1 ON RH1.ProcessID = RD1.ProcessID 
															And RH1.ProcessNo = RD1.ProcessNo 
															And RH1.FiscalYear = RD1.FiscalYear 
															And RH1.SerialNo = RD1.SerialNo
						WHERE RD1.ProcessID = 100 
						  AND (' + LTRIM(RTrim(Str(@ProcessNo))) + ' = 0 OR RD1.ProcessNo = ' + LTRIM(RTrim(Str(@ProcessNo))) + ')) Ret2 ON	Ret2.BaseProcessID = SD.ProcessID 
																																		AND Ret2.BaseProcessNo = SD.ProcessNo 
																																		AND Ret2.BaseFiscalYear = SD.FiscalYear 
																																		AND Ret2.BaseSerialNo = SD.SerialNo 
																																		AND Ret2.BaseDocRowNo = SD.DocRowNo 
																																		AND Ret2.DocDate > SD.DocDate 
			' + @StrWhereAfteSale_Rets + ' 
			 LEFT JOIN (SELECT RD1.*, 
							   RH1.TotalLineDiscount 
						FROM inv.tblStorageDocsDtl RD1 
						INNER JOIN inv.tblStorageDocsHdr RH1 ON RH1.ProcessID = RD1.ProcessID  
															AND RH1.ProcessNo = RD1.ProcessNo 
															AND RH1.FiscalYear = RD1.FiscalYear 
															AND RH1.SerialNo = RD1.SerialNo 
						WHERE RD1.ProcessID = 100 
						  AND (' + LTRIM(RTrim(Str(@ProcessNo))) + ' = 0 OR RD1.ProcessNo = ' + LTRIM(RTrim(Str(@ProcessNo))) + ')) Ret3 ON	Ret3.BaseProcessID = SD.ProcessID 
																																		And Ret3.BaseProcessNo = SD.ProcessNo 
																																		And Ret3.BaseFiscalYear = SD.FiscalYear 
																																		And Ret3.BaseSerialNo = SD.SerialNo 
																																		And Ret3BaseDocRowNo = SD.DocRowNo 
			' + @StrWhereAfteSale_RetsNoLimit + '						
			Where ' + @StrWhere + ' ) A
		GROUP BY ProcessID, ProcessNo, FiscalYear, SerialNo, DocRowNo, GoodsID
		'
	END
	
-- ******************** Typ-6
	IF @RetType = 6
	BEGIN
		SET @StrSelect1 = 
'		SELECT ProcessID, 
			   ProcessNo, 
			   FiscalYear, 
			   SerialNo, 
			   DocRowNo, 
			   GoodsID, 
			   ISNULL(SUM(' +
			   CASE WHEN @DeductTax = 0 And @DeductDiscount = 0 THEN 'A.RetPrice '
			        WHEN @DeductTax = 0 And @DeductDiscount = 1 THEN 'A.RetPrice - A.RetDiscountDtl '
			        WHEN @DeductTax = 1 And @DeductDiscount = 0 THEN 'A.RetPrice + A.RetTaxOverWorthCostDtl'
					ELSE 'A.RetPrice - A.RetDiscountDtl + A.RetTaxOverWorthCostDtl ' END + '),0)WithoutBaseDoc_Rets
		FROM(SELECT SD.ProcessID, 
				    SD.ProcessNo, 
				    SD.FiscalYear, 
				    SD.SerialNo, 
				    SD.DocRowNo, 
				    SD.GoodsID,
				    (ISNULL(SD.GoodsQuantity,0) * ISNULL(SD.GoodsPrice,0)) RetPrice, 
				    ISNULL(SD.DiscountDtl,0) RetDiscountDtl, 
				    (ISNULL(SD.TaxOverWorthCostDtl,0) + ISNULL(SD.TollOverWorthCostDtl,0)) RetTaxOverWorthCostDtl,
				    ISNULL(SH.TotalLineDiscount,0) RetDiscount				   
			 From inv.tblStorageDocsDtl SD
			 Inner Join inv.tblStorageDocsHdr SH ON SH.ProcessID = SD.ProcessID  
												AND SH.ProcessNo = SD.ProcessNo 
												AND SH.FiscalYear = SD.FiscalYear 
												AND SH.SerialNo = SD.SerialNo 	
			 WHERE ' + @StrWhere4 + ') A
		GROUP BY ProcessID, ProcessNo, FiscalYear, SerialNo, DocRowNo, GoodsID
		 '
	END
	
-- ******************** Typ-7
	IF @RetType = 7
	BEGIN
		SET @StrSelect1 = 
'		SELECT ProcessID, 
			   ProcessNo, 
			   FiscalYear, 
			   SerialNo, 
			   DocRowNo, 
			   GoodsID,
			   ISNULL(SUM(' +
			   CASE WHEN @DeductTax = 0 And @DeductDiscount = 0 THEN 'A.RetPrice '
			        WHEN @DeductTax = 0 And @DeductDiscount = 1 THEN 'A.RetPrice - A.RetDiscountDtl '
			        WHEN @DeductTax = 1 And @DeductDiscount = 0 THEN 'A.RetPrice + A.RetTaxOverWorthCostDtl'
					ELSE 'A.RetPrice - A.RetDiscountDtl + A.RetTaxOverWorthCostDtl ' END + '),0) WithBeforeDateSale
		FROM
		(
			SELECT SD.ProcessID, 
				   SD.ProcessNo, 
				   SD.FiscalYear, 
				   SD.SerialNo, 
				   SD.DocRowNo, 
				   SD.GoodsID, 
				   SD.BaseDocDate,
				   (ISNULL(SD.GoodsQuantity,0) * ISNULL(SD.GoodsPrice,0)) RetPrice, 
				   ISNULL(SD.DiscountDtl,0) RetDiscountDtl, 
				   (ISNULL(SD.TaxOverWorthCostDtl,0) + ISNULL(SD.TollOverWorthCostDtl,0)) RetTaxOverWorthCostDtl,
				   ISNULL(SH.TotalLineDiscount,0) RetDiscount
					   
			FROM inv.tblStorageDocsDtl SD
			INNER JOIN inv.tblStorageDocsHdr SH ON SH.ProcessID  = SD.ProcessID  
											   AND SH.ProcessNo = SD.ProcessNo 
											   AND SH.FiscalYear = SD.FiscalYear 
											   AND SH.SerialNo  = SD.SerialNo
				
			INNER JOIN (SELECT SD.* 
						FROM inv.tblStorageDocsDtl SD
						INNER JOIN inv.tblStorageDocsHdr SH ON SH.ProcessID = SD.ProcessID  
														   AND SH.ProcessNo = SD.ProcessNo 
														   AND SH.FiscalYear = SD.FiscalYear 
														   AND SH.SerialNo = SD.SerialNo
						WHERE ' + @StrWhere2 + ') Sale ON Sale.ProcessID = SD.BaseProcessID 
													  AND Sale.ProcessNo = SD.BaseProcessNo 
													  AND Sale.FiscalYear = SD.BaseFiscalYear 
													  AND Sale.SerialNo = SD.BaseSerialNo													   
			WHERE ' + @StrWhere3 + ') A
		GROUP BY ProcessID, ProcessNo, FiscalYear, SerialNo, DocRowNo, GoodsID
		'
	END
	
	SET @StrSelect1 = @StrSelect1 + @StrSelect2
	RETURN @StrSelect1;
	
-- =======================================================

END

