Create PROCEDURE [sms].[RptSMS_AccRemain]
	@AcntPartNo		int = 2,
	@AcntPartStart	int = 8,
	@AcntPartLen	int = 4,
	@SelectedAcnt1	Int = 0,
	@SelectedAcnt2	Int = 0,
	@SelectedAcnt3	Int = 0,
	@SelectedAcnt4	Int = 0,
	@DocDateFr		Char(10) = Null, 
	@DocDateTo		Char(10) = Null, 
	@RepOptions		varchar(20)= '0',
	@RepInfo		NVarChar(100) = '1@1@1'
AS

DECLARE @StrWhere	NVarChar(max);
DECLARE @StrWhereT	NVarChar(max);
DECLARE @StrSelect	NVarChar(max);

DECLARE @LangID		Char(1)
DECLARE @SessionNo	VarChar(10)
DECLARE @ReportID	VarChar(10)
DECLARE @MobileReq	bit;
DECLARE @RemainType		Char(2)

BEGIN
	SET NOCOUNT ON;
	
	-- Init Variables -----------------------------------------------
	If (@RepInfo	Is Null)	SET @RepInfo    = '1@1@1'

	IF (@SelectedAcnt1 Is Null)	SET @SelectedAcnt1 = 0;
	IF (@SelectedAcnt2 Is Null)	SET @SelectedAcnt2 = 0;
	IF (@SelectedAcnt3 Is Null)	SET @SelectedAcnt3 = 0;
	IF (@SelectedAcnt4 Is Null)	SET @SelectedAcnt4 = 0;
	
	SET	@LangID		= pub.funSplitString(@RepInfo, '@', 1);
	SET @SessionNo	= pub.funSplitString(@RepInfo, '@', 2);
	SET @ReportID	= pub.funSplitString(@RepInfo, '@', 3);

	set @MobileReq  = Substring(@RepOptions, 1, 1);
	set @RemainType = Substring(@RepOptions, 2, 1);
	
	-----------------------------------------------------------------
	if Substring(@RepOptions, 2, 1)='1' 
	set @RemainType='>'
	else
	set @RemainType='<='
	
	SELECT @StrWhere = '(1=1)'
	
	IF	(@SelectedAcnt1 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt1, 'V.AcntCode') 
	IF	(@SelectedAcnt2 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt2, 'V.AcntCode') 
	IF	(@SelectedAcnt3 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt3, 'V.AcntCode') 
	IF	(@SelectedAcnt4 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt4, 'V.AcntCode') 

	IF (@DocDateFr Is Not Null)
		SET @StrWhere = @StrWhere + ' AND (V.DocDate>=''' + @DocDateFr + ''')'
	IF (@DocDateTo Is Not Null)
		SET @StrWhere = @StrWhere + ' AND (V.DocDate<=''' + @DocDateTo + ''')'
	
	set @StrWhereT = '(AH.CodeClosed=0) and (AH.AcntCode is not null) and (AH.AcntCode <> '''')'

	if (@MobileReq = 1)
		set @StrWhereT = @StrWhereT + ' and (AH.SMSMobile<>'''')'

	SET @StrSelect = '
	select AH.AcntCode, isnull(V.Remain, 0) Remain, AH.SMSMobile, AD.AcntName
	from
	(
		select	Substring(V.AcntCode,' + ltrim(str(@AcntPartStart)) + ',' + ltrim(str(@AcntPartLen)) + ') AcntCode, 
			abs(isnull(SUM(Debit-Credit), 0)) Remain
		from	acc.tblVoucherDtl V
		where  ' + @StrWhere + '
		group BY Substring(V.AcntCode,' + ltrim(str(@AcntPartStart)) + ',' + ltrim(str(@AcntPartLen)) + ')
		having SUM(Debit-Credit) ' + @RemainType + ' 0 
	) V left  join acc.tblAcnt AH on AH.AcntCode = V.AcntCode and AH.PartNumber = ' + ltrim(str(@AcntPartNo)) + '
		left  join acc.tblAcntDtl AD on AD.AcntCode = AH.AcntCode and AD.PartNumber=AH.PartNumber
	where ' + @StrWhereT + '
	order by AH.AcntCode '

	PRINT @StrSelect
	EXEC sp_executesql @StrSelect;
END

