-- Author        : Zia
-- Create date   : 1392/01/26
-- Viewed By	 : 
-- Last Modified : 
-- Description   : 
-- =============================================
CREATE PROCEDURE [sms].[RptSMS_ImportantDays]
	@AcntPartNo		int = 2,
	@AcntPartStart	int = 8,
	@AcntPartLen	int = 4,
	@SelectedAcnt1	Int = 0,
	@SelectedAcnt2	Int = 0,
	@SelectedAcnt3	Int = 0,
	@SelectedAcnt4	Int = 0,
	@RepOptions		varchar(20)= '0',
	@RepInfo		NVarChar(100) = '1@1@1'
AS

DECLARE @StrWhere	NVarChar(max);
DECLARE @StrSelect	NVarChar(max);
DECLARE @MobileReq	bit;

DECLARE @LangID		Char(1)
DECLARE @SessionNo	VarChar(10)
DECLARE @ReportID	VarChar(10)
BEGIN
	SET NOCOUNT ON;
	
	-- Init Variables -----------------------------------------------
	If (@RepInfo	Is Null)	SET @RepInfo    = '1@1@1'

	IF (@SelectedAcnt1 Is Null)	SET @SelectedAcnt1 = 0;
	IF (@SelectedAcnt2 Is Null)	SET @SelectedAcnt2 = 0;
	IF (@SelectedAcnt3 Is Null)	SET @SelectedAcnt3 = 0;
	IF (@SelectedAcnt4 Is Null)	SET @SelectedAcnt4 = 0;
	
	SET	@LangID		= pub.funSplitString(@RepInfo, '@', 1);
	SET @SessionNo	= pub.funSplitString(@RepInfo, '@', 2);
	SET @ReportID	= pub.funSplitString(@RepInfo, '@', 3);

	set @MobileReq  = Substring(@RepOptions, 1, 1);
	-----------------------------------------------------------------
	
	SELECT @StrWhere = '(AH.CodeClosed=0) and (AH.AcntCode<>'''') and (AH.PartNumber=' + LTRIM(STR(@AcntPartNo)) + ')'
	
	if (@MobileReq = 1)
		set @StrWhere = @StrWhere + ' and (AH.SMSMobile<>'''')'
	
	IF	(@SelectedAcnt1 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt1, 'AH.AcntCode') 
	IF	(@SelectedAcnt2 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt2, 'AH.AcntCode') 
	IF	(@SelectedAcnt3 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt3, 'AH.AcntCode') 
	IF	(@SelectedAcnt4 > 0)
		SET @StrWhere = @StrWhere + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt4, 'AH.AcntCode') 

	SET @StrSelect = '
	select AH.AcntCode, AH.SMSMobile, AD.AcntName
	from acc.tblAcnt AH
			inner join acc.tblAcntDtl AD on AD.AcntCode = AH.AcntCode and AD.PartNumber = AH.PartNumber
	where ISNUMERIC(AH.SMSMobile)=1 And ' + @StrWhere + '
	order by AH.AcntCode '

	PRINT @StrSelect
	EXEC sp_executesql @StrSelect;
END

