CREATE PROCEDURE [sms].[RptSMS_LastBuy]
	@AcntPartNo		int = 2,
	@AcntPartStart	int = 8,
	@AcntPartLen	int = 4,
	@SelectedAcnt1	Int = 0,
	@SelectedAcnt2	Int = 0,
	@SelectedAcnt3	Int = 0,
	@SelectedAcnt4	Int = 0,
	@DocDateFr		Char(10) = Null, 
	@DocDateTo		Char(10) = Null, 
	@RepOptions		varchar(20)= '0',
	@RepInfo		NVarChar(100) = '1@1@1'
AS

DECLARE @StrWhereA	NVarChar(max);
DECLARE @StrWhereV	NVarChar(max);
DECLARE @StrWhereT	NVarChar(max);
DECLARE @StrSelect	NVarChar(max);
DECLARE @MobileReq	bit;

DECLARE @LangID		Char(1)
DECLARE @SessionNo	VarChar(10)
DECLARE @ReportID	VarChar(10)
BEGIN
	SET NOCOUNT ON;
	
	-- Init Variables -----------------------------------------------
	If (@RepInfo	Is Null)	SET @RepInfo    = '1@1@1'

	IF (@SelectedAcnt1 Is Null)	SET @SelectedAcnt1 = 0;
	IF (@SelectedAcnt2 Is Null)	SET @SelectedAcnt2 = 0;
	IF (@SelectedAcnt3 Is Null)	SET @SelectedAcnt3 = 0;
	IF (@SelectedAcnt4 Is Null)	SET @SelectedAcnt4 = 0;
	
	SET	@LangID		= pub.funSplitString(@RepInfo, '@', 1);
	SET @SessionNo	= pub.funSplitString(@RepInfo, '@', 2);
	SET @ReportID	= pub.funSplitString(@RepInfo, '@', 3);

	set @MobileReq  = Substring(@RepOptions, 1, 1);
	-----------------------------------------------------------------
    set @StrWhereA = '(A.PartNumber=' + ltrim(STR(@AcntPartNo)) + ')'
	set @StrWhereV = '(V.SourceProcessID=90)'
	set @StrWhereT = '(AH.CodeClosed=0)'
	
	IF	(@SelectedAcnt1 > 0)
		SET @StrWhereT = @StrWhereT + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt1, 'D.AcntCode') 
	IF	(@SelectedAcnt2 > 0)
		SET @StrWhereT = @StrWhereT + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt2, 'D.AcntCode') 
	IF	(@SelectedAcnt3 > 0)
		SET @StrWhereT = @StrWhereT + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt3, 'D.AcntCode') 
	IF	(@SelectedAcnt4 > 0)
		SET @StrWhereT = @StrWhereT + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt4, 'D.AcntCode') 

	IF	(@SelectedAcnt1 > 0)
		SET @StrWhereA = @StrWhereA + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt1, 'A.AcntCode') 
	IF	(@SelectedAcnt2 > 0)
		SET @StrWhereA = @StrWhereA + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt2, 'A.AcntCode') 
	IF	(@SelectedAcnt3 > 0)
		SET @StrWhereA = @StrWhereA + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt3, 'A.AcntCode') 
	IF	(@SelectedAcnt4 > 0)
		SET @StrWhereA = @StrWhereA + ' AND ' + pub.funGetFilterString(@SessionNo, @ReportID, @SelectedAcnt4, 'A.AcntCode') 

	IF (@DocDateFr Is Not Null)
		SET @StrWhereV = @StrWhereV + ' AND (V.DocDate>=''' + @DocDateFr + ''')'
	IF (@DocDateTo Is Not Null)
		SET @StrWhereV = @StrWhereV + ' AND (V.DocDate<=''' + @DocDateTo + ''')'
	
	if (@MobileReq = 1)
		set @StrWhereT = @StrWhereT + ' and (AH.SMSMobile<>'''')'

	SET @StrSelect = '
	SELECT	D.AcntCode, AH.SMSMobile, AD.AcntName
	FROM 
	( 
		select A.AcntCode  
		from acc.tblAcnt A  
		where  ' + @StrWhereA + '
		except  
		select SUBSTRING(V.AcntCode,' + ltrim(STR(@AcntPartStart)) + ',' + ltrim(STR(@AcntPartLen)) + ')
		from acc.tblVoucherDtl V  
		where  ' + @StrWhereV + '
	) D 
		inner join acc.tblAcnt	  AH ON D.AcntCode = AH.AcntCode AND AH.PartNumber = ' + ltrim(STR(@AcntPartNo)) + '
		inner join acc.tblAcntDtl AD ON D.AcntCode = AD.AcntCode AND AD.PartNumber = ' + ltrim(STR(@AcntPartNo)) + '
	WHERE  ' + @StrWhereT

	PRINT @StrSelect
	EXEC sp_executesql @StrSelect;
END
